/**
 * Everything the console does over time, as plain functions over a Host: the disk refresh and the event diff, the CLI
 * probes, the pane's lifecycle (auto-open without taking the keys), and the animation loop. Actions go through
 * ./runner. Nothing here reaches `$` but through the Host.
 */
import { actionsOf } from './bindings'
import type { Catalog } from './data/catalog'
import { PROBES, probeArgv, probeError, probeReady, type ProbeResult } from './data/cli'
import { ALL_COST_PROBES as COST_PROBES } from './data/cost-probes'
import { memmapProbe } from './data/memmap'
import { memoryHealthProbe } from './data/memory-health'
import { X_PROBES } from './data/xruv'
import { diffEvents, record } from './data/events'
import { agentName, announceChanges, factsOf, segmentOf, TOASTED_KEYS } from './notices'
import { plain } from './data/parse'
import { readSnapshot } from './data/snapshot'
import { sayGroundingHint } from './grounding'
import { markPicture } from './gfx/pictures'
import type { Host } from './host'
import { agentLogs } from './ops'
import { landingRefusal } from './model-tools'
import { createRunner, type Runner } from './runner'
import { advance, loadLedger, mcOf } from './mission-control'
import { hasLiveWork } from './mission-list'
import { loadAllowed } from './remember'
import { loadAiPrefs } from './settings'
import { openLoaders } from './view-open'
import { listSkills } from './skills'
import { readDrillLogs } from './drill-logs'
import { entryAge } from './menu-entry'
import { BOOT_MIN_MS, CLI_PREFIXES, isBooting, NAV_KEY, NAV_STYLES, PANE_ID, push, rowsOf, storeKeyOf, type State } from './state'
import type { Actions } from './views/common'
import { picturesOf } from './views/frames'
import { pulseDue } from './pulse'
import { refreshWorkflows } from './wf-live'
import { syncWhatsNew } from './whatsnew'
import { syncAdrDigest } from './adr-mission'

const ACTIVITY_BUCKET_MS = 5_000
const PANE_WATCH_MS = 1_000
const MAX_PARALLEL_PROBES = 2
const ALL_PROBES = [...PROBES, ...X_PROBES, ...COST_PROBES, memmapProbe, memoryHealthProbe] // CLI probes, the x.ruv.io board's network reads, cost, the memory map's list: one cadence and option gate
const BAR_FRESH_MS = 10_000
const IDLE_REFRESH_MS = 30_000
const TOOLS_RECOUNT_MS = 30_000

export type Controller = {
  refresh: () => Promise<void>
  probe: (force?: boolean) => Promise<void>
  start: () => void
  /** Restarts the pane's watch after a reload left the pane up and the timers gone. */
  resume: () => void
  stop: () => void
  open: (focus?: boolean) => Promise<{ isPlaced: boolean; reason: string }>
  /** At session start, with `panel: auto`: opens where it docks, never taking the keys; else leaves a hint. */
  autoOpen: () => void
  /** The person closed the pane (Esc, its mark): auto-open stands down until /ruflo opens it again. */
  closedByPerson: () => void
  close: () => Promise<void>
  setView: (view: State['view']) => void
  drill: (agentId: string) => void
  animate: () => void
  noteToolCall: (agentId: string | undefined, tool: string) => void
  actions: Actions
  runner: Runner
  host: Host
  /** The command catalog, once `/ruflo commands` has read it. */
  catalog?: Promise<Catalog>
  /** Blits the band's mark while Claude works; the band calls it with its requestId. */
  markFrame: (requestId: string, isWorking: boolean) => void
}

export function createController(state: State, host: Host): Controller {
  let activityCount = 0
  let markRequest: string | null = null
  let lastSegment: string | null | undefined
  let lastSpend: number | undefined
  let hasDrawn = false
  let toolsCountedAt = 0
  let inflight: Promise<void> | null = null
  const lastAttempt = new Map<string, number>()

  const persist = () => void host.storeSet(storeKeyOf(state.cwd), { view: state.view === 'agent' ? state.back : state.view, isClosedByPerson: state.pane.isClosedByPerson }).catch(() => undefined)
  const isVisible = () => state.pane.isOpen && state.pane.isShown

  function refresh(): Promise<void> {
    inflight ??= readAll().finally(() => {
      inflight = null
    })

    return inflight
  }

  /** A read that starts after this call: what an action checks, since a read already running may predate its write. */
  async function freshRead(): Promise<void> {
    await inflight?.catch(() => undefined)

    // A file the action just created must not wait out the missing-file backoff.
    for (const [path, held] of state.cache) {
      if ('missingUntilMs' in held) state.cache.delete(path)
    }

    await refresh()
  }

  async function readAll(): Promise<void> {
    state.isRefreshing = true

    const started = Date.now()

    try {
      // Claude Code connects MCP servers after the session starts: count the ruflo tools again now and then.
      if (Date.now() - toolsCountedAt >= TOOLS_RECOUNT_MS) {
        toolsCountedAt = Date.now()
        void host.rufloTools().then(counted => void (state.rufloTools = counted), () => undefined)
      }

      const [settings, usage, ruflo, route] = await Promise.all([
        host.settings().catch(() => null),
        host.usage().catch(() => null),
        host.rufloSnapshot().catch((error: unknown) => {
          state.ruflo.error = plain(String(error), 120)

          return null
        }),
        host.rufloRoute().catch(() => null),
      ])
      const previous = state.snapshot
      const now = Date.now()
      const snapshot = await readSnapshot(host.fs, state.cache, state.cwd, state.home, settings, now, state.configDir, state.options.federationNetwork)
      if (snapshot.hasNostrKey === false) state.nostrKeyVerifiedAtMs = null
      // What changed since the last read is announced on the band (the first read announces nothing).
      const before = previous === null ? null : factsOf(state, now)

      state.snapshot = snapshot
      syncWhatsNew(state, host)
      void syncAdrDigest(state, host).catch(() => undefined)
      sayGroundingHint(state, host)
      record(state.events, diffEvents(previous, snapshot, now))

      // A mission that finished or lost a task is said in a toast too: the band's notice row reaches only a person looking at the console.
      if (before !== null) for (const draft of announceChanges(state, before, now)) if (TOASTED_KEYS.has(draft.key)) host.toast(draft.text.slice(0, 120), 8000, draft.level === 'bad' ? 'error' : draft.level)

      if (route !== null && route.agent !== state.ruflo.route?.agent) record(state.events, [{ atMs: now, kind: 'learning', text: `router picked ${route.agent} (${Math.round(route.confidence * 100)}%)` }])

      state.usage = usage
      state.ruflo.snapshot = ruflo
      state.ruflo.route = route ?? ruflo?.lastRoute ?? null
      push(state.writes, snapshot.changed)
      for (const agent of snapshot.agents.slice(0, 200)) {
        const log = state.statusLog.get(agent.id) ?? []

        if (log.at(-1)?.status !== agent.status) push(log, { atMs: now, status: agent.status }, 100)
        state.statusLog.set(agent.id, log)
      }

      const patterns = snapshot.neural?.patterns
      if (patterns !== undefined && state.history.patterns.at(-1)?.value !== patterns) push(state.history.patterns, { atMs: now, value: patterns })
      if (usage?.costUsd !== undefined && state.history.spend.at(-1)?.value !== usage.costUsd) push(state.history.spend, { atMs: now, value: usage.costUsd })
      if ((snapshot.outcomes?.total ?? 0) > state.history.outcomes) {
        if (state.history.outcomes > 0) state.curveGrewAtMs = now
        state.history.outcomes = snapshot.outcomes?.total ?? 0
      }

      if (state.options.bar === 'off') {
        const text = segmentOf(state)

        if (text !== lastSegment) {
          lastSegment = text
          void host.rufloSegment(text).catch(() => undefined)
        }
      }
    } catch (error) {
      state.ruflo.error = plain(String(error), 120)
    } finally {
      state.isRefreshing = false
      push(state.stats.refreshes, Date.now() - started, 200)

      // Redraw only for something new while the pane is closed: the band need not repaint an unchanged line.
      const spend = state.usage?.costUsd

      if (state.pane.isOpen || (state.snapshot?.changed ?? 0) > 0 || spend !== lastSpend || !hasDrawn) {
        hasDrawn = true
        lastSpend = spend
        host.invalidate()
      }
    }
  }

  const probesInFlight = new Map<string, Promise<void>>()

  /** One probe run at a time per probe: a second ask while it runs joins it. */
  function runProbe(probe: (typeof ALL_PROBES)[number]): Promise<void> {
    const held = probesInFlight.get(probe.id)

    if (held !== undefined) return held

    const run = runProbeOnce(probe).finally(() => probesInFlight.delete(probe.id))

    probesInFlight.set(probe.id, run)

    return run
  }

  async function runProbeOnce(probe: (typeof ALL_PROBES)[number]): Promise<void> {
    const held: ProbeResult = state.probes.get(probe.id) ?? { value: null, okAtMs: null, error: null, errorAtMs: null, isRunning: false }

    state.probes.set(probe.id, { ...held, isRunning: true })
    lastAttempt.set(probe.id, Date.now())

    try {
      const argv = probeArgv(probe, state.options.cli, state)
      const result = await host.run(argv, probe.timeoutMs)
      const value = result.exitCode === 0 ? (probe.parse(result.stdout) as unknown) : null
      state.probes.set(
        probe.id,
        value !== null
          ? { value, okAtMs: Date.now(), error: null, errorAtMs: held.errorAtMs, isRunning: false }
          : {
              ...held,
              isRunning: false,
              errorAtMs: Date.now(),
              error: probeError(argv, result),
            },
      )
    } catch (error) {
      state.probes.set(probe.id, { ...held, isRunning: false, errorAtMs: Date.now(), error: plain(error instanceof Error ? error.message : String(error), 100) || 'refused' })
    } finally {
      host.invalidate()
    }
  }

  /** Runs the probes the view in front draws, each no more often than its cadence; `force` ignores the cadence. */
  async function probe(force = false): Promise<void> {
    const now = Date.now()
    const due = ALL_PROBES.filter(
      entry =>
        (isVisible() || force) &&
        entry.views.includes(state.view) &&
        (!entry.isNetwork || state.options.federationNetwork) && probeReady(entry, state) &&
        (force || (state.probes.get(entry.id)?.isRunning !== true && now - (lastAttempt.get(entry.id) ?? 0) >= entry.everyMs)),
    )

    for (let i = 0; i < due.length; i += MAX_PARALLEL_PROBES) {
      await Promise.all(due.slice(i, i + MAX_PARALLEL_PROBES).map(entry => runProbe(entry)))
    }
  }

  function every(name: string, ms: number, fn: () => void): void {
    if (!state.timers.has(name)) state.timers.set(name, host.every(ms, fn))
  }

  function cancel(name: string): void {
    state.timers.get(name)?.cancel()
    state.timers.delete(name)
  }

  // Whether the last frame drew the boot screen: when it ends the whole pane redraws once, and an unfocused pane's loop stops again.
  let wasBooting = false

  /** One frame of every picture of the view in front, each blitted only at the size it was mounted. */
  function frame(): void {
    const started = Date.now()
    const booting = isBooting(state, started)

    if (wasBooting && !booting) {
      wasBooting = false
      state.pane.menuAtMs = Date.now()
      host.invalidate()
      animate()

      return
    }

    wasBooting = booting

    if (pulseDue(state.view, started) || (state.view === 'menu' && entryAge({ look: state.options.look, boot: state.options.boot, ...state.pane }, started, BOOT_MIN_MS) !== null)) host.invalidate()

    for (const [key, grid] of picturesOf(state, state.pane.columns, Date.now(), Date.now())) {
      const mounted = state.mounted.get(key)

      if (mounted !== undefined && mounted.columns === grid.columns && mounted.rows === grid.rows) {
        host.blit({ requestId: PANE_ID, key, cells: grid.encode(), columns: grid.columns, rows: grid.rows })
      }
    }

    push(state.stats.frames, Date.now() - started, 200)
  }

  /** Runs the frame loop while the pane is shown and holds the keys (or plays the boot screen), at `fps`; stops it otherwise. */
  function animate(): void {
    // Something in progress moves its spinner, pictured or not: a lab action in flight, or a live mission, task or guidance run on the Missions page.
    const moving = state.lab.running !== null || (state.view === 'missions' && hasLiveWork(state.snapshot?.missions?.missions ?? [], mcOf(state).guidance?.status === 'running'))

    if (!(state.options.fps > 0 && isVisible() && (state.pane.isFocused || isBooting(state, Date.now())) && (state.mounted.size > 0 || moving))) return cancel('frames')

    every('frames', Math.round(1000 / state.options.fps), frame)
  }

  /** Watches whether the pane is shown and focused, so the loop stops behind another tab and resumes in front. */
  async function watchPane(): Promise<void> {
    const panes = await host.panes().catch(() => null)
    const mine = panes?.find(pane => pane.id === PANE_ID)

    if (panes !== null) {
      state.pane.isOpen = mine !== undefined
      state.pane.isShown = mine?.isShown === true
      state.pane.isFocused = mine?.isFocused === true
    }

    if (!state.pane.isOpen) cancel('watch')

    animate()
  }

  function start(): void {
    let lastIdleMs = 0

    // The AI terminal's saved model and budget apply from the first turn, not only once Settings was opened.
    void loadAiPrefs(state, host)
    void loadAllowed(state, host)
    void loadLedger(state, host)
    void host.storeGet(NAV_KEY).then(saved => {
      const style = NAV_STYLES.find(candidate => candidate === saved)

      if (style !== undefined) state.nav = style
    }, () => undefined)

    every('refresh', state.options.refreshSeconds * 1000, () => {
      const now = Date.now()
      const isSeen = state.pane.isOpen || now - state.barDrawnAtMs < BAR_FRESH_MS

      // Nothing on screen reads the disk: re-read only on the idle cadence, so a closed console costs nearly nothing.
      if (isSeen || now - lastIdleMs >= IDLE_REFRESH_MS) {
        lastIdleMs = now
        void refresh().then(() => {
          void probe()
          void refreshWorkflows(state, host)
          advance(state, host)
        })
      }
    })
    every('activity', ACTIVITY_BUCKET_MS, () => {
      push(state.activity, activityCount)
      activityCount = 0
    })
  }

  const resume = () => every('watch', PANE_WATCH_MS, () => void watchPane())

  function stop(): void {
    for (const timer of state.timers.values()) timer.cancel()
    state.timers.clear()
  }

  /** `closeOnEscape` false: take the keys but leave Esc handing them back, as an auto-opened pane does. */
  async function open(focus = true, closeOnEscape = focus): Promise<{ isPlaced: boolean; reason: string }> {
    try {
      const result = await host.openPane({ id: PANE_ID, title: 'ruflo', rows: rowsOf(state.view), ...(state.dockColumns > 0 && { columns: state.dockColumns }), ...(focus && { focus: true, holdToasts: true }), ...(closeOnEscape && { closeOnEscape: true }) })
      const isPlaced = result === undefined || result.isPlaced !== false

      if (isPlaced && !state.pane.isOpen) state.pane.bootAtMs = Date.now()
      state.pane.isOpen = isPlaced
      state.pane.isShown = isPlaced
      if (focus) state.pane.isClosedByPerson = false
      if (isPlaced) persist()
      resume()
      void refresh().then(() => probe(true))

      return { isPlaced, reason: result?.reason ?? '' }
    } catch (error) {
      return { isPlaced: false, reason: plain(error instanceof Error ? error.message : String(error), 160) }
    }
  }

  function autoOpen(): void {
    if (state.options.panel !== 'auto' || state.snapshot?.isRufloProject !== true || state.pane.isOpen || state.pane.isClosedByPerson || state.pane.autoTried) return

    state.pane.autoTried = true
    // From a timer, never a render hook; without `focus`, so the prompt keeps the keys. The engine seats an unasked pane
    // only where it docks (144 columns and up) and answers why not otherwise: the band then says "/ruflo to open".
    state.timers.set(
      'auto-open',
      host.after(50, () => {
        state.timers.delete('auto-open')
        // /ruflo <view> may have opened it in the meantime: that choice stands.
        if (state.pane.isOpen) return
        // The BBS look opens on its main menu, as a board does after login.
        if (state.options.look === 'bbs') state.view = 'menu'
        void open(false).then(result => {
          state.pane.autoReason = result.isPlaced ? '' : result.reason || 'not placed'
          host.invalidate()
        })
      }),
    )
  }

  async function close(): Promise<void> {
    state.pane.isOpen = false
    state.pane.isShown = false
    state.pane.isClosedByPerson = true
    persist()
    cancel('frames')
    cancel('watch')
    await host.closePane(PANE_ID).catch(() => undefined)
  }

  function setView(view: State['view']): void {
    state.isHelp = false
    state.palette.isOpen = false

    if (view !== state.view) {
      if (view === 'agent' || state.view !== 'agent') state.back = state.view === 'agent' ? state.back : state.view
      state.view = view
      // A group picked on one page (the menu's pages row) does not follow you to the next, or back to this one.
      state.navPick = null
      state.pane.viewAtMs = Date.now()
      state.select.item = 0
      state.mounted.clear()
      persist()
      // A new view asks for its own height inline; the dock ignores it.
      if (state.pane.isOpen) void host.openPane({ id: PANE_ID, title: 'ruflo', rows: rowsOf(view), ...(state.dockColumns > 0 && { columns: state.dockColumns }) }).catch(() => undefined)
      void probe(true)
      host.scrollTop()
    }

    host.invalidate()
    // The terminal is for typing: its field takes the keys as it opens, so letters reach it, not the pane's hotkeys.
    if (view === 'terminal') focusField('term-input')
    // Opening the skills view is the person asking for its lists (npx skills reaches the network, so never unasked).
    if (view === 'skills') {
      void listSkills(state, host)
      focusField('skills-search')
    }
    openLoaders(state, host, view)
  }

  /**
   * Puts the keys in one of the pane's fields. A pane that opened by itself (panel=auto) does not hold the keys, and a
   * mouse click on a tab does not give them, so a person who clicked their way to the terminal would type into
   * Claude's prompt instead. Here the pane takes the keys first (an open with focus), then the ring moves to the field.
   */
  function focusField(key: string): void {
    if (!state.pane.isOpen) return

    const toField = () => void host.focus(PANE_ID, key).catch(() => undefined)

    if (state.pane.isFocused) toField()
    else void open(true, false).then(result => result.isPlaced && toField())
  }

  function drill(agentId: string): void {
    const agent = state.snapshot?.agents.find(entry => entry.id === agentId)

    state.drill = { agentId, logs: null, logsAtMs: 0 }
    setView('agent')

    const spec = agent === undefined ? null : agentLogs(agent)

    if (spec !== null) readDrillLogs(state, host, agentId, spec.args)
  }

  const runner = createRunner(state, host, {
    freshRead, setView, drill,
    command: name => (name === 'refresh' ? actions.refresh() : name === 'help' ? actions.help() : actions.close()),
    landingRefusal: pending => landingRefusal(state, pending),
  })
  const actions: Actions = actionsOf(state, host, runner, { freshRead, probe, setView, drill, close, animate })

  function markFrame(requestId: string, isWorking: boolean): void {
    markRequest = requestId

    if (isWorking && state.options.fps > 0) {
      every('mark', Math.round(1000 / state.options.fps), () => {
        if (markRequest !== null) host.blit({ requestId: markRequest, key: 'mark', cells: markPicture(true, Date.now()).encode(), columns: 2, rows: 1 })
      })
    } else {
      cancel('mark')
    }
  }

  function noteToolCall(agentId: string | undefined, tool: string): void {
    activityCount += 1

    const who = agentId ?? 'main'
    const list = state.toolsByAgent.get(who) ?? []

    push(list, { atMs: Date.now(), tool: plain(tool, 40) }, 200)
    state.toolsByAgent.set(who, list)
    if (state.toolsByAgent.size > 50) state.toolsByAgent.delete(state.toolsByAgent.keys().next().value as string)
    record(state.events, [{ atMs: Date.now(), kind: 'tools', text: `${agentName(state, agentId)}: ${plain(tool, 40)}` }])
  }

  const closedByPerson = () => {
    state.pane.isClosedByPerson = true
    persist()
  }

  return { refresh, probe, start, resume, stop, open, autoOpen, closedByPerson, close, setView, drill, animate, noteToolCall, actions, runner, markFrame, host }
}

files.hooks/sessions.ts:
/**
 * The session workspace's runtime (ADR-486): one Workspace per console state (a side table, so nothing a transcript said can reach the state
 * that is snapshotted, exported or shown to a model), the scan that fills it, the selection, and the "read means viewed" commit.
 *
 * Scans are stat-first and incremental (data/harness-track.ts): a fast pass once a second while the pane is shown, a full relist every 15 s,
 * and almost nothing while it is closed. Nothing here starts a process, makes a model call, or touches a session it lists.
 */
import { buildIndex, type Index, type Scanned } from './data/sessions-index'
import { attentionOf, countsOf, markViewed, viewedOf, type AttentionItem, type Viewed } from './data/sessions-attention'
import { claudeAdapter } from './data/harness-claude'
import { codexAdapter } from './data/harness-codex'
import { rufloAdapter, type LedgerFacts, type RufloInput } from './data/harness-ruflo'
import type { HarnessAdapter, SessionFs } from './data/harness'
import { mcOf } from './mission-control'
import { replaceFile } from './activity-io'
import type { Host } from './host'
import type { State } from './state'

/** The fold key of the Sessions section (views/common.ts `section`: present means flipped from its default, which is closed). */
export const SESSIONS_FOLD = 'room/sessions'
export const VIEWED_KEY = 'ruflo-console/sessions-viewed'
const FAST_MS = 1000
const FULL_MS = 15_000
const CLOSED_MS = 30_000
const SHOWN_TTL_MS = 10_000

export type Workspace = {
  adapters: HarnessAdapter[]
  index: Index | null
  selected: string | null
  /** Which attention row the cursor is on (an index into the queue). */
  cursor: number
  viewed: Viewed | null
  scanning: boolean
  lastScanMs: number
  lastFullMs: number
  scanTimes: number[]
  /** Rows whose preview text a frame actually drew, with when: the page's evidence that content was displayed (data/sessions-attention.ts). */
  shown: Map<string, number>
  /** A line about the last action that could not run, with its reason. */
  note: string
  signature: string
  /** The counts last written to the summary file, so it is rewritten only when one changes. */
  summary: string
  timer: { cancel: () => void } | null
}

const spaces = new WeakMap<State, Workspace>()

export function rufloInputOf(state: State, nowMs: number): RufloInput {
  const ledger = new Map<string, LedgerFacts>()

  for (const mission of mcOf(state).missions.values()) ledger.set(mission.id, { ...(mission.adrs !== undefined && { adrs: mission.adrs }), tasks: mission.tasks.map(task => ({ id: task.id, dependsOn: task.dependsOn, ...(task.rufloTaskId !== undefined && { rufloTaskId: task.rufloTaskId }) })) })

  return { cwd: state.cwd, missions: state.snapshot?.missions ?? null, agents: state.snapshot?.agents ?? [], nowMs, ledger, claimedIssues: new Set((state.snapshot?.claims ?? []).filter(claim => claim.status !== 'released').map(claim => claim.issueId)) }
}

export function workspaceOf(state: State): Workspace {
  let found = spaces.get(state)

  if (found === undefined) {
    found = { adapters: [claudeAdapter(), codexAdapter(), rufloAdapter(() => rufloInputOf(state, Date.now()))], index: null, selected: null, cursor: 0, viewed: null, scanning: false, lastScanMs: 0, lastFullMs: 0, scanTimes: [], shown: new Map(), note: '', signature: '', summary: '', timer: null }
    spaces.set(state, found)
  }

  return found
}

/** The native ids of the sessions the console itself started (the terminal's saved conversations): everything else is outside Ruflo. */
export const ownIds = (state: State): ReadonlySet<string> => new Set(Object.values(state.terminal.sessions).filter((id): id is string => typeof id === 'string'))

const codexDirOf = (state: State): string | null => (state.home === null ? null : `${state.home.replace(/\/+$/, '')}/.codex`)

/** One pass over every adapter. Never rejects; a failing adapter leaves its report saying so and keeps its earlier rows. */
export async function scanSessions(state: State, host: Pick<Host, 'fs' | 'invalidate'>, full: boolean, nowMs: number = Date.now()): Promise<void> {
  const ws = workspaceOf(state)

  if (ws.scanning) return

  ws.scanning = true

  const started = performance.now()

  try {
    const env = { fs: host.fs as SessionFs, claudeDir: state.configDir, codexDir: codexDirOf(state), nowMs, full }
    const scans: Scanned[] = await Promise.all(
      ws.adapters.map(async adapter => ({
        id: adapter.id,
        label: adapter.label,
        capabilities: adapter.capabilities,
        result: await adapter.scan(env).catch(() => ({ state: 'failed' as const, rows: [], note: 'the scan threw; nothing was read' })),
      })),
    )

    ws.index = buildIndex(scans, ownIds(state), nowMs)
    ws.lastScanMs = nowMs
    if (full) ws.lastFullMs = nowMs
    if (ws.selected !== null && !ws.index.rows.some(row => row.key === ws.selected)) ws.selected = null
    ws.scanTimes.push(performance.now() - started)
    if (ws.scanTimes.length > 50) ws.scanTimes.shift()

    const signature = `${ws.index.rows.map(row => `${row.key}:${row.updatedMs}:${row.status}:${row.stale ?? ''}`).join(',')}|${state.pending?.label ?? ''}`

    if (signature !== ws.signature) {
      ws.signature = signature
      if (state.view === 'room' || state.view === 'overview') host.invalidate()
    }
  } finally {
    ws.scanning = false
  }
}

/** The queue as the page draws it (the console's own pending confirm included). Empty until the viewed state has loaded. */
export function queueOf(state: State): AttentionItem[] {
  const ws = workspaceOf(state)

  if (ws.index === null || ws.viewed === null) return state.pending === null ? [] : attentionOf([], { baselineMs: Date.now(), seen: {} }, { label: state.pending.label, askedAtMs: state.pending.askedAtMs })

  return attentionOf(ws.index.rows, ws.viewed, state.pending === null ? null : { label: state.pending.label, askedAtMs: state.pending.askedAtMs })
}

export const attentionCounts = (state: State) => countsOf(queueOf(state))

/** Selecting a row changes only which row is looked at: no read, no process, no wake. */
export function selectRow(state: State, key: string | null): void {
  const ws = workspaceOf(state)

  ws.selected = key !== null && ws.index?.rows.some(row => row.key === key) === true ? key : null
  ws.note = ''
}

/** The view calls this when it drew a row's preview text. It only notes the fact; `commitViewed` acts on it. */
export function noteShown(state: State, key: string, atMs: number = Date.now()): void {
  workspaceOf(state).shown.set(key, atMs)
}

/**
 * Read means viewed: an unread completion or a failure clears only for a row whose preview text a frame drew in the last few seconds while
 * the Room was the page in front. A placeholder, an error line, a hidden pane or another page clears nothing. Returns whether anything cleared.
 */
export function commitViewed(state: State, host: Pick<Host, 'storeSet' | 'invalidate'>, nowMs: number = Date.now()): boolean {
  const ws = workspaceOf(state)

  for (const [key, at] of ws.shown) if (nowMs - at > SHOWN_TTL_MS) ws.shown.delete(key)

  if (ws.viewed === null || state.view !== 'room' || !state.pane.isShown || ws.shown.size === 0) return false

  const items = queueOf(state).filter(item => item.rowKey !== null && ws.shown.has(item.rowKey))
  const next = markViewed(ws.viewed, items)

  ws.shown.clear()

  if (next === ws.viewed) return false

  ws.viewed = next
  void host.storeSet(VIEWED_KEY, next).catch(() => undefined)
  host.invalidate()

  return true
}

/** Where the counts-only summary ruflo-mods can show lives: the console's own state folder, in a ruflo project, rewritten only when a count changes. */
export const ATTENTION_FILE = '.claude-flow/console/attention.json'

export async function mirrorAttention(state: State, host: Pick<Host, 'fs' | 'run'>, nowMs: number = Date.now()): Promise<void> {
  const ws = workspaceOf(state)

  if (ws.viewed === null || ws.index === null || state.snapshot?.isRufloProject !== true) return

  const counts = attentionCounts(state)
  const key = `${counts['needs-approval']}/${counts.question}/${counts.failed}/${counts['completed-unread']}`

  if (key === ws.summary) return

  ws.summary = key
  // Counts only: no title, path or transcript text is in this file.
  const text = `${JSON.stringify({ schema: 'ruflo-console.attention/1', approve: counts['needs-approval'], question: counts.question, failed: counts.failed, unread: counts['completed-unread'], atMs: nowMs })}\n`

  if ((await replaceFile(host, state.cwd, `${state.cwd.replace(/\/+$/, '')}/${ATTENTION_FILE}`, text)) !== null) ws.summary = ''
}

export type SessionActions = {
  select: (key: string) => void
  /** Moves the selection through the rows in the order the page lists them. */
  move: (by: number) => void
  /** Selects the session an attention item is about (the console's own confirm has none). */
  jump: (itemId: string) => void
  refresh: () => void
  /** Enter on a row: opens it natively only where the harness declared it can; otherwise says why not. */
  open: (key: string) => void
}

export function sessionActions(state: State, host: Pick<Host, 'fs' | 'invalidate'>): SessionActions {
  const ws = workspaceOf(state)
  const order = () => ws.index?.groups.flatMap(group => group.rows) ?? []

  return {
    select: key => {
      selectRow(state, key)
      host.invalidate()
    },
    move: by => {
      const rows = order()
      const at = rows.findIndex(row => row.key === ws.selected)

      if (rows.length > 0) selectRow(state, rows[Math.max(0, Math.min(rows.length - 1, (at < 0 ? (by > 0 ? -1 : rows.length) : at) + by))]?.key ?? null)
      host.invalidate()
    },
    jump: id => {
      const item = queueOf(state).find(candidate => candidate.id === id)

      if (item?.rowKey != null) {
        selectRow(state, item.rowKey)
        // The browser starts folded so the Room's own sections stay in view; jumping to a session opens it.
        state.sections.add(SESSIONS_FOLD)
      }
      host.invalidate()
    },
    refresh: () => void scanSessions(state, host, true),
    open: key => {
      const row = ws.index?.rows.find(candidate => candidate.key === key)
      const caps = ws.index?.reports.find(report => report.id === row?.harness)?.capabilities

      ws.note = row === undefined ? 'that session is gone' : caps?.resume.supported === true ? 'this harness can open sessions, but phase 1 wires no opener' : `open is unavailable for ${row.harness}: ${caps?.resume.why ?? 'not declared'}`
      host.invalidate()
    },
  }
}

/** Starts the watcher once. A closed pane scans rarely; a shown one every second (stat-only unless something changed). */
export function startSessions(state: State, host: Host): void {
  const ws = workspaceOf(state)

  if (ws.timer !== null) return

  // The baseline is the first time this queue ever ran: older completions are history, not unread. It is stored so a restart keeps it.
  void host.storeGet(VIEWED_KEY).then(
    raw => {
      ws.viewed = viewedOf(raw, Date.now())
      if (typeof raw !== 'object' || raw === null) void host.storeSet(VIEWED_KEY, ws.viewed).catch(() => undefined)
    },
    () => (ws.viewed = viewedOf(null, Date.now())),
  )

  ws.timer = host.every(FAST_MS, () => {
    if (!state.options.sessionWorkspace) return

    const now = Date.now()
    const isSeen = state.pane.isOpen && state.pane.isShown

    if (!isSeen && now - ws.lastScanMs < CLOSED_MS) return

    void scanSessions(state, host, now - ws.lastFullMs >= FULL_MS, now).then(() => {
      commitViewed(state, host)
      void mirrorAttention(state, host, now)
    })
  })
}

files.hooks/data/events.ts:
/**
 * The event stream: what changed between two reads of ruflo's state, plus what the console observed itself (tool calls,
 * routes, mod admissions, permission denies). Every event is something that happened on disk or in this session, with
 * the time the console saw it: the stream never synthesises activity.
 */
import type { Snapshot } from './snapshot'

export type EventKind = 'swarm' | 'claims' | 'federation' | 'learning' | 'tools' | 'mods' | 'missions' | 'workflows' | 'autopilot' | 'anatole' | 'notices' | 'other'

export type ConsoleEvent = {
  atMs: number
  kind: EventKind
  text: string
  /** The ruflo agent the event concerns, when one does: the topology pulses along that agent's edge. */
  agentId?: string
  /** What the event is about, as `agent:<id>`, `claim:<id>`, `run:<id>`, `task:<id>`, `mission:<id>` or `step:<id>`; derived by `refOf` when absent. */
  ref?: string
  /** Which part of the console saw it, when not the diff of two reads: `autopilot`, `workflows`, `anatole`, `notices`, `session`. */
  src?: string
}

export const EVENT_KINDS: readonly EventKind[] = ['swarm', 'claims', 'federation', 'learning', 'tools', 'mods', 'missions', 'workflows', 'autopilot', 'anatole', 'notices', 'other']

export const isEventKind = (value: unknown): value is EventKind => typeof value === 'string' && (EVENT_KINDS as readonly string[]).includes(value)

/** What an event is about: its own `ref`, else the agent it names, else the first issue or mission id in the words of a claims or missions event. */
export function refOf(event: ConsoleEvent): string | undefined {
  if (event.ref !== undefined) return event.ref
  if (event.agentId !== undefined) return `agent:${event.agentId}`

  const word = /^(?:task |mission |proposal )?([A-Za-z0-9][\w.:-]{2,60})/.exec(event.text)?.[1]

  if (word === undefined) return undefined
  if (event.kind === 'claims') return `${event.text.startsWith('task ') ? 'task' : 'claim'}:${word}`
  if (event.kind === 'missions') return `mission:${word}`

  return undefined
}
export const MAX_EVENTS = 300

const ev = (atMs: number, kind: EventKind, text: string, agentId?: string): ConsoleEvent => ({ atMs, kind, text, ...(agentId !== undefined && { agentId }) })

/** What changed from `prev` to `next`. The first read (no `prev`) is a baseline and yields nothing. */
export function diffEvents(prev: Snapshot | null, next: Snapshot, atMs: number): ConsoleEvent[] {
  if (prev === null) {
    return []
  }

  const out: ConsoleEvent[] = []
  const before = new Map(prev.agents.map(agent => [agent.id, agent]))
  const after = new Map(next.agents.map(agent => [agent.id, agent]))

  if (prev.swarm?.id !== next.swarm?.id && next.swarm !== null) out.push(ev(atMs, 'swarm', `swarm ${next.swarm.id} (${next.swarm.topology}) appeared`))
  if (prev.swarm !== null && next.swarm !== null && prev.swarm.id === next.swarm.id && prev.swarm.status !== next.swarm.status) {
    out.push(ev(atMs, 'swarm', `swarm ${next.swarm.status} (was ${prev.swarm.status})`))
  }

  for (const [id, agent] of after) {
    const old = before.get(id)

    if (old === undefined) out.push(ev(atMs, 'swarm', `agent ${agent.name ?? agent.type} spawned (${agent.type})`, id))
    else if (old.status !== agent.status) out.push(ev(atMs, 'swarm', `agent ${agent.name ?? agent.type}: ${old.status} → ${agent.status}`, id))
  }

  for (const [id, agent] of before) {
    if (!after.has(id)) out.push(ev(atMs, 'swarm', `agent ${agent.name ?? agent.type} left the store`, id))
  }

  const claimsBefore = new Map(prev.claims.map(claim => [claim.issueId, claim]))
  const claimsAfter = new Map(next.claims.map(claim => [claim.issueId, claim]))

  for (const [id, claim] of claimsAfter) {
    const old = claimsBefore.get(id)
    const owner = claim.claimant.kind === 'agent' ? claim.claimant.id : undefined

    if (old === undefined) out.push(ev(atMs, 'claims', `${id} claimed by ${claim.claimant.agentType ?? claim.claimant.name ?? claim.claimant.id}`, owner))
    else if (old.claimant.id !== claim.claimant.id) out.push(ev(atMs, 'claims', `${id} now held by ${claim.claimant.agentType ?? claim.claimant.id}`, owner))
    else if (old.status !== claim.status) out.push(ev(atMs, 'claims', `${id}: ${old.status} → ${claim.status}${claim.handoffTo !== undefined ? ` (to ${claim.handoffTo})` : ''}`, owner))
    else if ((old.progress ?? 0) !== (claim.progress ?? 0)) out.push(ev(atMs, 'claims', `${id} progress ${claim.progress ?? 0}%`, owner))
  }

  for (const [id, claim] of claimsBefore) {
    if (!claimsAfter.has(id)) out.push(ev(atMs, 'claims', `${id} released`, claim.claimant.kind === 'agent' ? claim.claimant.id : undefined))
  }

  const tasksBefore = new Set(prev.tasks.map(task => task.id))

  for (const task of next.tasks) {
    if (!tasksBefore.has(task.id)) out.push(ev(atMs, 'claims', `task ${task.id} created: ${task.description.slice(0, 60)}`))
  }

  const proposals = new Set(prev.hive?.pending.map(entry => entry.id) ?? [])
  const decided = new Set(prev.hive?.history.map(entry => entry.id) ?? [])

  for (const proposal of next.hive?.pending ?? []) {
    if (!proposals.has(proposal.id)) out.push(ev(atMs, 'swarm', `proposal ${proposal.type} (${proposal.strategy}) opened`, next.hive?.queen))
  }

  for (const decision of next.hive?.history ?? []) {
    if (!decided.has(decision.id)) out.push(ev(atMs, 'swarm', `proposal ${decision.type} decided: ${decision.result} (${decision.votesFor}/${decision.votesAgainst})`, next.hive?.queen))
  }

  // Each ballot new since the last read, tagged with its voter: the hive's honeycomb pulses that worker's cell.
  const ballotsBefore = new Map(prev.hive?.pending.map(entry => [entry.id, new Set(entry.ballots.map(ballot => ballot.voter))]) ?? [])

  for (const proposal of next.hive?.pending ?? []) {
    const seen = ballotsBefore.get(proposal.id) ?? new Set<string>()

    for (const ballot of proposal.ballots) {
      if (!seen.has(ballot.voter)) out.push(ev(atMs, 'swarm', `${ballot.voter} voted ${ballot.isFor ? 'for' : 'against'} ${proposal.type} (${proposal.id})`, ballot.voter))
    }
  }

  const workersBefore = new Set(prev.hive?.workers ?? [])
  const workersAfter = new Set(next.hive?.workers ?? [])

  for (const worker of workersAfter) if (!workersBefore.has(worker)) out.push(ev(atMs, 'swarm', `${worker} joined the hive`, worker))
  for (const worker of workersBefore) if (!workersAfter.has(worker)) out.push(ev(atMs, 'swarm', `${worker} left the hive`, worker))

  const patterns = (next.neural?.patterns ?? 0) - (prev.neural?.patterns ?? 0)

  if (prev.neural !== null && next.neural !== null && patterns > 0) out.push(ev(atMs, 'learning', `+${patterns} pattern${patterns === 1 ? '' : 's'} learned`))

  const outcomes = (next.outcomes?.total ?? 0) - (prev.outcomes?.total ?? 0)

  if (prev.outcomes !== null && outcomes > 0) out.push(ev(atMs, 'learning', `+${outcomes} routed outcome${outcomes === 1 ? '' : 's'} judged`))
  if ((prev.federationNodes?.length ?? 0) !== (next.federationNodes?.length ?? 0)) out.push(ev(atMs, 'federation', `federation keys: ${next.federationNodes?.length ?? 0} node ids on disk`))
  const missionsBefore = new Map((prev.missions?.missions ?? []).map(mission => [mission.id, mission]))

  for (const mission of next.missions?.missions ?? []) {
    const old = missionsBefore.get(mission.id)

    if (old === undefined) out.push(ev(atMs, 'missions', `mission ${mission.id} (${mission.state}): ${mission.objective.slice(0, 60)}`))
    else if (old.state !== mission.state) out.push(ev(atMs, 'missions', `mission ${mission.id}: ${old.state} → ${mission.state}`))
    else if (old.evidence.verified !== mission.evidence.verified) out.push(ev(atMs, 'missions', `mission ${mission.id}: ${mission.evidence.verified}/${mission.evidence.count} evidence verified`))
  }

  if (prev.hasNostrKey !== next.hasNostrKey && next.hasNostrKey === true) out.push(ev(atMs, 'federation', 'a nostr identity appeared (~/.ruflo/nostr.key)'))

  return out
}

/** Appends events, newest last, keeping at most MAX_EVENTS. */
export function record(events: ConsoleEvent[], fresh: readonly ConsoleEvent[]): void {
  if (fresh.length === 0) return

  events.push(...fresh)

  if (events.length > MAX_EVENTS) events.splice(0, events.length - MAX_EVENTS)
}

/** The agents an event touched in the last `windowMs`, newest event per agent: what the topology pulses for. */
export function recentByAgent(events: readonly ConsoleEvent[], nowMs: number, windowMs: number): Map<string, number> {
  const out = new Map<string, number>()

  for (let i = events.length - 1; i >= 0; i--) {
    const event = events[i] as ConsoleEvent

    if (nowMs - event.atMs > windowMs) break
    if (event.agentId !== undefined && !out.has(event.agentId)) out.set(event.agentId, event.atMs)
  }

  return out
}

files.hooks/data/parse.ts:
/**
 * Readers for the swarm files ruflo writes under `.claude-flow/` and `.swarm/`.
 *
 * Vendored from plugins/ruflo-swarm/hooks/reader/parse.ts (a mod may import only its own files), cut to what the console
 * draws, with the claim record extended by its timestamps and context. Every one takes text another process wrote, so
 * each tolerates any shape: what it cannot read is left out, never guessed. Nothing here keeps the hive's `hiveToken`.
 */
import { countOf, ratioOf, timeOf } from './safe'

/** Text longer than this is not parsed: a store that size is not one the CLI wrote, and parsing it would stall a hook. */
export const MAX_TEXT = 4_000_000
/** At most this many records of one kind are kept; the rest are counted, not drawn. */
export const MAX_RECORDS = 1_000

const ID = /^[A-Za-z0-9][A-Za-z0-9._:@-]{0,127}$/

// Whole escape sequences go first (the CLI colours its output; a hostile file may carry a hyperlink or a title): stripping only the ESC byte
// would leave `[1m` or `]8;;https://…` in the text. Written as \u escapes so no invisible character sits in this source.
export const ESCAPES = new RegExp('\\u001b\\][^\\u0007\\u001b]*(?:\\u0007|\\u001b\\\\|(?=\\u001b)|$)|\\u009d[^\\u0007\\u009c\\u009d]*(?:[\\u0007\\u009c]|(?=\\u009d)|$)|(?:\\u001b\\[|\\u009b)[0-9;?]*[ -/]*[@-~]', 'g')
// Controls, DEL, C1, soft hyphen, combining grapheme joiner, Arabic letter mark, zero-width and bidi characters, invisible operators,
// variation selectors, Hangul fillers and BOM: nothing a person could read, all of them fit for hiding or reordering text.
export const HIDDEN = new RegExp('[\\u0000-\\u001f\\u007f-\\u009f\\u00ad\\u034f\\u061c\\u115f\\u1160\\u17b4\\u17b5\\u180b-\\u180f\\u200b-\\u200f\\u2028\\u2029\\u202a-\\u202e\\u2060-\\u206f\\u3164\\ufe00-\\ufe0d\\ufeff\\uffa0\\ufff9-\\ufffb]|[\\u{e0000}-\\u{e0fff}]', 'gu')

/** The zero-width and format characters that can split a credential or a keyword without being seen: removed (not spaced) before any mask or pattern runs. */
export const INVISIBLE = new RegExp('[\\u00ad\\u034f\\u061c\\u115f\\u1160\\u17b4\\u17b5\\u180b-\\u180f\\u200b-\\u200f\\u202a-\\u202e\\u2060-\\u206f\\u3164\\ufe00-\\ufe0f\\ufeff\\uffa0\\ufff9-\\ufffb]|[\\u{e0000}-\\u{e0fff}]', 'gu')

/** Plain printable text of at most `max` characters: no escape sequence, control, hidden or bidi-override character reaches the terminal. */
export function plain(value: unknown, max = 200): string {
  if (typeof value !== 'string') {
    return ''
  }

  const cleaned = value.replace(ESCAPES, '').replace(INVISIBLE, '').replace(HIDDEN, ' ').replace(/\s+/g, ' ').trim()

  return cleaned.length <= max ? cleaned : `${cleaned.slice(0, Math.max(0, max - 1))}…`
}

/** An id as ruflo mints them (`agent-…`, `swarm-…`, `proposal-…`), or null: only such a string ever reaches an argv. */
export function idOf(value: unknown): string | null {
  return typeof value === 'string' && ID.test(value) ? value : null
}

export const numberOf = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) ? value : undefined)
export const stringOf = (value: unknown, max = 80): string | undefined => (typeof value === 'string' && value !== '' ? plain(value, max) || undefined : undefined)
export const recordOf = (value: unknown): Record<string, unknown> | null =>
  value !== null && typeof value === 'object' && !Array.isArray(value) ? (value as Record<string, unknown>) : null

/** JSON text to a plain object, or null for anything else (too long, malformed, an array, a scalar). */
export function jsonObject(text: string | null | undefined): Record<string, unknown> | null {
  if (typeof text !== 'string' || text.length > MAX_TEXT) {
    return null
  }

  try {
    return recordOf(JSON.parse(text))
  } catch {
    return null
  }
}

export const valuesOf = (value: unknown): unknown[] => {
  const record = recordOf(value)

  return record === null ? [] : Object.values(record).slice(0, MAX_RECORDS)
}

/** An ISO time to epoch milliseconds, or undefined. */
export const msOf = (value: unknown): number | undefined => {
  if (typeof value === 'number' && Number.isFinite(value) && value > 0) {
    return timeOf(value)
  }

  const parsed = typeof value === 'string' ? Date.parse(value) : Number.NaN

  return Number.isFinite(parsed) ? parsed : undefined
}

export type SwarmInfo = { id: string; topology: string; status: string; maxAgents?: number; strategy?: string; agentIds: string[]; updatedAt?: string }
export type AgentRecord = { id: string; type: string; name?: string; status: string; health?: number; taskCount?: number; createdAtMs?: number }
export type TaskRecord = {
  id: string
  type: string
  description: string
  status: string
  assignedTo: string[]
  createdAtMs?: number
  /** `mission:<id>` / `task:<id>` style labels (plain words only), as `task_create` stored them. */
  tags?: string[]
  startedAtMs?: number
  completedAtMs?: number
  /** What `task_complete` / `task_update` recorded as the result, flattened to `key: value` text (bounded). */
  resultText?: string
}
export type Claimant = { kind: 'agent' | 'human'; id: string; agentType?: string; name?: string }
export type ClaimRecord = {
  issueId: string
  status: string
  claimant: Claimant
  progress?: number
  handoffTo?: string
  isStealable: boolean
  claimedAtMs?: number
  changedAtMs?: number
  /** ruflo's claim type declares `expiresAt`, but no claims tool sets it today: absent means no TTL, not an expired one. */
  expiresAtMs?: number
  context?: string
}
/** One worker's vote on a proposal, as `votes` records it: the voter's id and whether it voted for. */
export type Ballot = { voter: string; isFor: boolean }
export type Proposal = {
  id: string
  type: string
  status: string
  strategy: string
  votesFor: number
  votesAgainst: number
  /** Who voted which way, in the order the store lists them. */
  ballots: Ballot[]
  /** Voters the CLI excluded as Byzantine (bft proposals only). */
  byzantine: string[]
  value?: string
  proposedBy?: string
  proposedAtMs?: number
  /** Raft: the term the proposal belongs to, and when it may be re-proposed in the next one. */
  term?: number
  timeoutAtMs?: number
  /** Quorum: unanimous, majority or supermajority. */
  quorumPreset?: string
}
export type Decision = { id: string; type: string; result: string; votesFor: number; votesAgainst: number; strategy?: string; term?: number; decidedAtMs?: number; byzantine: number }
/** A message `hive-mind broadcast` left in the hive's shared memory. */
export type Broadcast = { id: string; message: string; priority: string; from: string; atMs?: number }
export type HiveInfo = {
  topology: string
  strategy?: string
  queen?: string
  queenTerm?: number
  queenElectedAtMs?: number
  workers: string[]
  pending: Proposal[]
  history: Decision[]
  /** The newest broadcasts, oldest first, and every shared-memory key (values are not kept: they are anyone's JSON). */
  broadcasts: Broadcast[]
  memoryKeys: string[]
  createdAtMs?: number
  updatedAtMs?: number
}
/** A worker `hive-mind spawn` wrote to `.claude-flow/agents.json`, with the role it was given in the hive. */
export type HiveAgentRecord = AgentRecord & { role?: string }

/** `.claude-flow/swarm/swarm-state.json`: the running swarm, else the one updated last. */
export function parseSwarmStore(text: string | null): SwarmInfo | null {
  const swarms = valuesOf(jsonObject(text)?.swarms).flatMap(entry => {
    const swarm = recordOf(entry)
    const id = idOf(swarm?.swarmId)

    if (swarm === null || id === null) {
      return []
    }

    const config = recordOf(swarm.config)
    const info: SwarmInfo = {
      id,
      topology: stringOf(swarm.topology, 40) ?? 'unknown',
      status: stringOf(swarm.status, 40) ?? 'unknown',
      agentIds: (Array.isArray(swarm.agents) ? swarm.agents : []).slice(0, MAX_RECORDS).flatMap(agent => {
        const agentId = idOf(agent) ?? idOf(recordOf(agent)?.agentId) ?? idOf(recordOf(agent)?.id)

        return agentId !== null ? [agentId] : []
      }),
    }
    const maxAgents = countOf(swarm.maxAgents)
    const strategy = stringOf(config?.strategy, 40)
    const updatedAt = stringOf(swarm.updatedAt, 40)

    if (maxAgents !== undefined) info.maxAgents = maxAgents
    if (strategy !== undefined) info.strategy = strategy
    if (updatedAt !== undefined) info.updatedAt = updatedAt

    return [info]
  })
  // By instant, not text: "…T10:00+02:00" is older than "…T09:00Z" though it sorts after it as a string. Unparseable sorts last.
  const byRecency = (a: SwarmInfo, b: SwarmInfo) => (msOf(b.updatedAt) ?? -Infinity) - (msOf(a.updatedAt) ?? -Infinity) || 0

  return [...swarms.filter(swarm => swarm.status === 'running')].sort(byRecency)[0] ?? [...swarms].sort(byRecency)[0] ?? null
}

/** `.swarm/state.json`: the pointer `swarm init` (or `swarm start`) leaves. */
export function parseSwarmPointer(text: string | null): { id: string; topology?: string; strategy?: string; status?: string } | null {
  const value = jsonObject(text)
  const id = idOf(value?.id) ?? idOf(value?.swarmId)

  if (value === null || id === null) {
    return null
  }

  const pointer: { id: string; topology?: string; strategy?: string; status?: string } = { id }
  const topology = stringOf(value.topology, 40)
  const strategy = stringOf(value.strategy, 40)
  const status = stringOf(value.status, 40)

  if (topology !== undefined) pointer.topology = topology
  if (strategy !== undefined) pointer.strategy = strategy
  if (status !== undefined) pointer.status = status

  return pointer
}

/** `.claude-flow/agents/store.json`. */
export function parseAgents(text: string | null): AgentRecord[] {
  return valuesOf(jsonObject(text)?.agents).flatMap(entry => {
    const agent = recordOf(entry)
    const id = idOf(agent?.agentId)

    if (agent === null || id === null) {
      return []
    }

    const record: AgentRecord = { id, type: stringOf(agent.agentType, 40) ?? 'agent', status: stringOf(agent.status, 20) ?? 'unknown' }
    const name = stringOf(agent.name, 40)
    const health = ratioOf(agent.health)
    const taskCount = countOf(agent.taskCount)
    const createdAtMs = msOf(agent.createdAt)

    if (name !== undefined) record.name = name
    if (health !== undefined) record.health = health
    if (taskCount !== undefined) record.taskCount = taskCount
    if (createdAtMs !== undefined) record.createdAtMs = createdAtMs

    return [record]
  })
}

/** `.claude-flow/tasks/store.json`. */
/** A task's result object as one bounded line of `key: value` pairs (strings and numbers only), or undefined. */
function resultTextOf(value: unknown): string | undefined {
  const result = recordOf(value)

  if (result === null) return typeof value === 'string' ? plain(value, 400) || undefined : undefined

  const text = Object.entries(result)
    .slice(0, 8)
    .flatMap(([key, v]) => (typeof v === 'string' || typeof v === 'number' || typeof v === 'boolean' ? [`${plain(key, 24)}: ${plain(String(v), 160)}`] : []))
    .join(' · ')

  return text === '' ? undefined : text.slice(0, 500)
}

export function parseTasks(text: string | null): TaskRecord[] {
  return valuesOf(jsonObject(text)?.tasks).flatMap(entry => {
    const task = recordOf(entry)
    const id = idOf(task?.taskId)

    return task === null || id === null
      ? []
      : [
          {
            id,
            type: stringOf(task.type, 40) ?? 'task',
            description: plain(task.description, 200),
            status: stringOf(task.status, 20) ?? 'unknown',
            assignedTo: (Array.isArray(task.assignedTo) ? task.assignedTo : []).slice(0, 50).flatMap(agent => (idOf(agent) !== null ? [agent as string] : [])),
            ...(msOf(task.createdAt) !== undefined && { createdAtMs: msOf(task.createdAt) }),
            tags: (Array.isArray(task.tags) ? task.tags : []).slice(0, 12).flatMap(tag => (typeof tag === 'string' && /^[A-Za-z0-9_.:-]{1,90}$/.test(tag) ? [tag] : [])),
            ...(msOf(task.startedAt) !== undefined && { startedAtMs: msOf(task.startedAt) }),
            ...(msOf(task.completedAt) !== undefined && { completedAtMs: msOf(task.completedAt) }),
            ...(resultTextOf(task.result) !== undefined && { resultText: resultTextOf(task.result) }),
          },
        ]
  })
}

function claimantOf(value: unknown): Claimant | null {
  const claimant = recordOf(value)

  if (claimant === null) {
    return null
  }

  const isAgent = claimant.type === 'agent'
  const id = idOf(isAgent ? claimant.agentId : claimant.userId)

  if (id === null) {
    return null
  }

  const who: Claimant = { kind: isAgent ? 'agent' : 'human', id }
  const agentType = stringOf(claimant.agentType, 40)
  const name = stringOf(claimant.name, 40)

  if (agentType !== undefined) who.agentType = agentType
  if (name !== undefined) who.name = name

  return who
}

/** `.claude-flow/claims/claims.json`: issue claims (who works on what), not the authorization file `.claude-flow/claims.json`. */
export function parseClaims(text: string | null): ClaimRecord[] {
  const store = jsonObject(text)
  const stealable = recordOf(store?.stealable) ?? {}

  return valuesOf(store?.claims).flatMap(entry => {
    const claim = recordOf(entry)
    const issueId = idOf(claim?.issueId)
    const claimant = claimantOf(claim?.claimant)

    if (claim === null || issueId === null || claimant === null) {
      return []
    }

    const handoff = recordOf(claim.handoffTo)
    const handoffTo = idOf(handoff?.agentId ?? handoff?.userId)
    const record: ClaimRecord = {
      issueId,
      status: stringOf(claim.status, 30) ?? 'unknown',
      claimant,
      isStealable: claim.status === 'stealable' || Object.hasOwn(stealable, issueId),
    }
    const progress = numberOf(claim.progress)
    const claimedAtMs = msOf(claim.claimedAt)
    const changedAtMs = msOf(claim.statusChangedAt)
    const expiresAtMs = msOf(claim.expiresAt)
    const context = stringOf(claim.context, 120)

    if (progress !== undefined) record.progress = Math.max(0, Math.min(100, progress))
    if (handoffTo !== null) record.handoffTo = handoffTo
    if (claimedAtMs !== undefined) record.claimedAtMs = claimedAtMs
    if (changedAtMs !== undefined) record.changedAtMs = changedAtMs
    if (expiresAtMs !== undefined) record.expiresAtMs = expiresAtMs
    if (context !== undefined) record.context = context

    return [record]
  })
}

const votesOf = (value: unknown): { votesFor: number; votesAgainst: number; ballots: Ballot[] } => {
  const ballots = Object.entries(recordOf(value) ?? {})
    .slice(0, MAX_RECORDS)
    .flatMap(([voter, vote]) => (idOf(voter) !== null && typeof vote === 'boolean' ? [{ voter, isFor: vote }] : []))

  return { votesFor: ballots.filter(ballot => ballot.isFor).length, votesAgainst: ballots.filter(ballot => !ballot.isFor).length, ballots }
}

const idsOf = (value: unknown, max = 50): string[] => (Array.isArray(value) ? value : []).slice(0, max).flatMap(entry => (idOf(entry) !== null ? [entry as string] : []))

/** A proposal's value as one bounded line: a string as it is, anything else as its JSON. */
function valueText(value: unknown): string | undefined {
  if (typeof value === 'string') return stringOf(value, 120)
  if (value === undefined || value === null) return undefined

  try {
    return stringOf(JSON.stringify(value).slice(0, 400), 120)
  } catch {
    return undefined
  }
}

function proposalOf(entry: unknown): Proposal | null {
  const proposal = recordOf(entry)
  const id = idOf(proposal?.proposalId)

  if (proposal === null || id === null) return null

  const out: Proposal = {
    id,
    type: stringOf(proposal.type, 40) ?? 'proposal',
    status: stringOf(proposal.status, 20) ?? 'pending',
    strategy: stringOf(proposal.strategy, 20) ?? 'unknown',
    ...votesOf(proposal.votes),
    byzantine: idsOf(proposal.byzantineVoters),
  }
  const value = valueText(proposal.value)
  const proposedBy = idOf(proposal.proposedBy)
  const proposedAtMs = msOf(proposal.proposedAt)
  const term = numberOf(proposal.term)
  const timeoutAtMs = msOf(proposal.timeoutAt)
  const quorumPreset = stringOf(proposal.quorumPreset, 20)

  if (value !== undefined) out.value = value
  if (proposedBy !== null) out.proposedBy = proposedBy
  if (proposedAtMs !== undefined) out.proposedAtMs = proposedAtMs
  if (term !== undefined) out.term = term
  if (timeoutAtMs !== undefined) out.timeoutAtMs = timeoutAtMs
  if (quorumPreset !== undefined) out.quorumPreset = quorumPreset

  return out
}

function decisionOf(entry: unknown): Decision | null {
  const decision = recordOf(entry)
  const id = idOf(decision?.proposalId)
  const votes = recordOf(decision?.votes)

  if (decision === null || id === null) return null

  const out: Decision = {
    id,
    type: stringOf(decision.type, 40) ?? 'proposal',
    result: stringOf(decision.result, 20) ?? 'unknown',
    votesFor: countOf(votes?.for) ?? 0,
    votesAgainst: countOf(votes?.against) ?? 0,
    byzantine: idsOf(decision.byzantineDetected).length,
  }
  const strategy = stringOf(decision.strategy, 20)
  const term = numberOf(decision.term)
  const decidedAtMs = msOf(decision.decidedAt)

  if (strategy !== undefined) out.strategy = strategy
  if (term !== undefined) out.term = term
  if (decidedAtMs !== undefined) out.decidedAtMs = decidedAtMs

  return out
}

/** `sharedMemory.broadcasts`, the last 20, each field bounded: the message is free text another process wrote. */
function broadcastsOf(value: unknown): Broadcast[] {
  return (Array.isArray(value) ? value : []).slice(-20).flatMap(entry => {
    const message = recordOf(entry)
    const id = idOf(message?.messageId)
    const text = stringOf(message?.message, 160)

    if (message === null || id === null || text === undefined) return []

    const atMs = msOf(message.timestamp)

    return [{ id, message: text, priority: stringOf(message.priority, 12) ?? 'normal', from: idOf(message.fromId) ?? 'system', ...(atMs !== undefined && { atMs }) }]
  })
}

/** `.claude-flow/hive-mind/state.json`, without its capability token. */
export function parseHive(text: string | null): HiveInfo | null {
  const hive = jsonObject(text)

  if (hive === null || hive.initialized !== true) {
    return null
  }

  const queen = recordOf(hive.queen)
  const queenId = idOf(queen?.agentId)
  const consensus = recordOf(hive.consensus)
  const shared = recordOf(hive.sharedMemory)
  const info: HiveInfo = {
    topology: stringOf(hive.topology, 40) ?? 'unknown',
    workers: idsOf(hive.workers, MAX_RECORDS),
    pending: (Array.isArray(consensus?.pending) ? consensus.pending : []).slice(-50).flatMap(entry => proposalOf(entry) ?? []),
    history: (Array.isArray(consensus?.history) ? consensus.history : []).slice(-50).flatMap(entry => decisionOf(entry) ?? []),
    broadcasts: broadcastsOf(shared?.broadcasts),
    memoryKeys: Object.keys(shared ?? {}).slice(0, 200).flatMap(key => (idOf(key) !== null ? [key] : [])),
  }
  const strategy = stringOf(hive.consensusStrategy, 30)
  const term = numberOf(queen?.term)
  const electedAtMs = msOf(queen?.electedAt)
  const createdAtMs = msOf(hive.createdAt)
  const updatedAtMs = msOf(hive.updatedAt)

  if (strategy !== undefined) info.strategy = strategy
  if (queenId !== null) info.queen = queenId
  if (term !== undefined) info.queenTerm = term
  if (electedAtMs !== undefined) info.queenElectedAtMs = electedAtMs
  if (createdAtMs !== undefined) info.createdAtMs = createdAtMs
  if (updatedAtMs !== undefined) info.updatedAtMs = updatedAtMs

  return info
}

/** `.claude-flow/agents.json`: the workers `hive-mind spawn` writes (the other agent tools use agents/store.json), with their hive role. */
export function parseHiveAgents(text: string | null): HiveAgentRecord[] {
  const roles = new Map(
    valuesOf(jsonObject(text)?.agents).flatMap(entry => {
      const agent = recordOf(entry)
      const id = idOf(agent?.agentId)
      const role = stringOf(recordOf(agent?.config)?.hiveRole, 20)

      return id !== null && role !== undefined ? [[id, role] as const] : []
    }),
  )

  return parseAgents(text).map(agent => {
    const role = roles.get(agent.id)

    return role === undefined ? agent : { ...agent, role }
  })
}

/** The tail of an id a person can tell apart at a glance: `agent-1790954653916-od014i` → `od014i`. */
export function shortId(id: string): string {
  const tail = id.split(/[-_:]/).pop() ?? id

  return tail.length >= 4 ? tail.slice(-6) : id.slice(-6)
}

/** One readable label per agent: its name, else its type, with a short id only where two would read the same. */
export function agentLabels(agents: readonly { id: string; name?: string; type: string }[]): Map<string, string> {
  const base = (agent: { name?: string; type: string }) => agent.name ?? agent.type
  const counts = new Map<string, number>()

  for (const agent of agents) counts.set(base(agent), (counts.get(base(agent)) ?? 0) + 1)

  return new Map(agents.map(agent => [agent.id, (counts.get(base(agent)) ?? 0) > 1 ? `${base(agent)}·${shortId(agent.id).slice(-4)}` : base(agent)]))
}

