import { plain } from './data/parse'
import type { Host } from './host'
import { CLI_PREFIXES, type State } from './state'

/** Reads an agent's last log lines for the drill-down (through the ruflo CLI, 30 s at most) and redraws when they arrive; a stale answer for another agent is dropped. */
export function readDrillLogs(state: State, host: Host, agentId: string, args: readonly string[]): void {
  void host
    .run([...CLI_PREFIXES[state.options.cli], ...args], 30_000)
    .then(result => {
      if (state.drill.agentId === agentId) state.drill = { agentId, logs: result.stdout.split('\n').map(line => plain(line, 160)).filter(Boolean).slice(-12), logsAtMs: Date.now() }
    })
    .catch(() => undefined)
    .finally(() => host.invalidate())
}

files.hooks/menu-entry.ts:
/**
 * The main menu's entry, played once after the boot (and again when Refresh restarts the console): the four group cards light up one
 * after another, each title scrambling into place and its entries locking in one by one, then the status bar and the prompt. Pure and
 * a leaf (no imports): the menu asks for its age and draws what that age allows. Total about seven seconds. Tested in tests/menu-entry.spec.ts.
 */
export const ENTRY = { groupFrom: 500, groupEvery: 900, titleMs: 600, itemAfter: 500, itemEvery: 110, settleMs: 350, statusFrom: 5600, factsFrom: 6300, promptFrom: 6200, totalMs: 6900 } as const

export type EntryClock = { look: string; boot: boolean; bootAtMs: number; menuAtMs: number }

/** Ms since the menu's entry began, or null when there is no entry to play (not the BBS look, boot off, never opened, or it has finished). */
export function entryAge(clock: EntryClock, nowMs: number, bootMinMs: number): number | null {
  if (clock.look !== 'bbs' || !clock.boot || clock.bootAtMs === 0) return null

  const start = clock.menuAtMs >= clock.bootAtMs && clock.menuAtMs > 0 ? clock.menuAtMs : clock.bootAtMs + bootMinMs
  const age = nowMs - start

  return age >= ENTRY.totalMs ? null : Math.max(0, age)
}

export const groupStart = (group: number): number => ENTRY.groupFrom + group * ENTRY.groupEvery
export const itemStart = (group: number, item: number): number => groupStart(group) + ENTRY.itemAfter + item * ENTRY.itemEvery

files.hooks/pulse.ts:
/**
 * The Learning page's pulse is text drawn from the clock, so the page needs to be redrawn while it is in front: about three times a
 * second (every 350 ms), from the frame loop, which only runs while the pane is shown and focused. No other page asks.
 */
let last = 0

export function pulseDue(view: string, nowMs: number): boolean {
  if (view !== 'learning') return false

  const slot = Math.floor(nowMs / 350)

  if (slot === last) return false

  last = slot

  return true
}

files.hooks/wf-live.ts:
/**
 * The Workflows page's refresh (ADR-464), kept out of the controller: it reads Claude Code's run folders through the host's
 * read-only `fs` only while the page is the one in front, once per refresh tick (the controller's own cadence, the pane's
 * `refreshSeconds`), and never while the pane is closed or hidden. A read still running is joined, not stacked. A failed
 * read keeps the runs already on screen and says why. After a read the notice slots are asked what changed (views/wf-slots.ts),
 * and the page itself announces a run that finished or failed, from the change between two reads only: the first read announces nothing.
 */
import { cleanRun, cleanText } from './data/wf-clean'
import { readWorkflowRuns, type WorkflowFs } from './data/workflows-read'
import { allRuns, startOn } from './data/workflows-nav'
import type { WfRun } from './data/workflows'
import { plain } from './data/parse'
import type { Host } from './host'
import { addNotice, type NoticeDraft } from './notices'
import type { State } from './state'
import { slotsFor } from './views/wf-slots'
import type { WorkflowsModel } from './views/workflows'

/** What runs after each successful read, registered once by hooks/wf-wire.ts (a module that needs this one cannot be imported here). */
export type AfterRead = (state: State, host: Host, before: readonly WfRun[] | null, runs: readonly WfRun[], nowMs: number) => void | Promise<void>
export const afterRead: AfterRead[] = []

/** The notices one read raises: a workflow run that ended since the last read (finished, or failed), seen against each run's earlier state. */
export function runNotices(prev: ReadonlyMap<string, string> | null, next: readonly WfRun[]): NoticeDraft[] {
  if (prev === null) return []

  const out: NoticeDraft[] = []

  for (const run of next) {
    const before = prev.get(run.id)

    if (before === undefined || before === run.state) continue
    if (run.state === 'completed' || run.state === 'finished') out.push({ level: 'ok', text: `workflow ${run.name} finished: ${run.done}/${run.total} agents`, key: `wf-${run.id}-done`, go: 'workflows' })
    else if (run.state === 'failed') out.push({ level: 'bad', text: `workflow ${run.name} failed: ${run.failed} of ${run.total} agents`, key: `wf-${run.id}-failed`, go: 'workflows' })
  }

  return out
}

/** The page's model for this frame: the read runs with the ruflo swarm folded in; null before the first read finishes. */
export function workflowsModelOf(state: State, nowMs: number): WorkflowsModel | null {
  const read = state.wf.read

  if (read === null) return null

  return { runs: allRuns(read.runs, state.snapshot?.swarm ?? null, state.snapshot?.agents ?? [], nowMs), root: read.root, capBytes: read.capBytes, skipped: read.skipped, more: read.more }
}

/**
 * Reads the runs now if the page is in front and the pane is shown (or there is no pane, as in a dump). `force` skips the
 * pane check for the open of the page itself. Resolves when the read is done or was not needed.
 */
export async function refreshWorkflows(state: State, host: Host, force = false, nowMs: number = Date.now()): Promise<void> {
  if (state.view !== 'workflows' || state.wf.isReading) return
  if (!force && state.isInteractive && !(state.pane.isOpen && state.pane.isShown)) return

  const wf = state.wf

  wf.isReading = true

  try {
    const result = await readWorkflowRuns(host.fs as WorkflowFs, state.cache, { configDir: state.configDir, cwd: state.cwd, nowMs })
    const runs = result.runs.map(cleanRun)
    const first = wf.read === null
    const prev = wf.seen
    const before = wf.read?.runs ?? null

    wf.read = { runs, root: result.root, capBytes: result.capBytes, skipped: result.skipped.length, more: result.more }
    wf.readAtMs = nowMs
    wf.error = null
    wf.seen = new Map(runs.map(run => [run.id, run.state]))

    // The cursor starts on the phase the first run is in; later reads leave it where the person put it.
    if (first) wf.ui = startOn(wf.ui, allRuns(runs, state.snapshot?.swarm ?? null, state.snapshot?.agents ?? [], nowMs)[0] ?? null)

    for (const draft of runNotices(prev, runs)) addNotice(state, draft, nowMs)

    for (const slot of slotsFor('notice')) {
      try {
        for (const draft of slot.between(before, runs, nowMs)) addNotice(state, { ...draft, text: cleanText(draft.text), key: `${slot.id}:${plain(draft.key, 40)}` }, nowMs)
      } catch {
        // A slot that throws raises nothing; the page still reads.
      }
    }

    for (const hook of afterRead) {
      try {
        await hook(state, host, before, runs, nowMs)
      } catch {
        // A hook that throws loses its own work only.
      }
    }
  } catch (error) {
    wf.error = cleanText(plain(error instanceof Error ? error.message : String(error), 100)) || 'the read was refused'
  } finally {
    wf.isReading = false
    host.invalidate()
  }
}

files.hooks/adr-mission.ts:
/**
 * ADRs on a mission (ADR-480): attach, suggest and detach, the digest Claude and the swarm read (and the file the swarm reads it from), the
 * comparison of changed files with the attached ADRs' paths, and a draft record from a mission. The page's logic is in adr.ts; the pure
 * parts are in data/adr-scope.ts. Nothing here blocks anything: a scope hit is a warning in the mission record.
 */
import { replaceFile } from './activity-io'
import { adrOf, announce, docOf, proposeSpec, root, say } from './adr'
import type { ActionSpec } from './actions'
import type { AdrDoc } from './data/adr'
import { checkScope, digestBlock, reportLines, suggest, type Suggestion } from './data/adr-scope'
import { draftFromMission } from './data/adr-write'
import { loadAdrs } from './adr'
import { plain } from './data/parse'
import type { Host } from './host'
import { activeMission, record, saveLedger } from './mission-control'
import type { MissionRecord } from './mission-types'
import type { State } from './state'


export const MAX_ATTACH = 8
const FILE_SAFE = /^[A-Za-z0-9][A-Za-z0-9._ -]{0,119}\.md$/

/** The file names a mission has attached, validated (a saved ledger is not trusted). */
export const attachedOf = (mission: MissionRecord): string[] => (Array.isArray(mission.adrs) ? mission.adrs.filter((file): file is string => typeof file === 'string' && FILE_SAFE.test(file)).slice(0, MAX_ATTACH) : [])

/** The attached records that are in this project's folder now (an attached file that was removed simply is not listed). */
export const attachedDocs = (state: State, mission: MissionRecord): AdrDoc[] => attachedOf(mission).flatMap(file => docOf(state, file) ?? [])

/** What Claude and the swarm agents read for a mission: the digest block, or '' with no ADR attached. */
export const adrBlockFor = (state: State, mission: MissionRecord | null): string => (mission === null ? '' : digestBlock(attachedDocs(state, mission)))

export function suggestFor(state: State, mission: MissionRecord | null, goal: string): Suggestion[] {
  return suggest(goal, adrOf(state).registry.docs, mission === null ? [] : attachedOf(mission))
}

export async function setAttached(state: State, host: Host, file: string, on: boolean): Promise<void> {
  const mission = activeMission(state)

  if (mission === null) return say(state, host, 'attach ADR', false, ['no active mission: create one in Missions first'])
  if (!FILE_SAFE.test(file) || docOf(state, file) === undefined) return say(state, host, 'attach ADR', false, [`${plain(file, 60)} is not an ADR in this project`])

  const now = attachedOf(mission)

  if (on && !now.includes(file) && now.length >= MAX_ATTACH) return say(state, host, 'attach ADR', false, [`a mission carries at most ${MAX_ATTACH} ADRs`])

  mission.adrs = on ? [...new Set([...now, file])] : now.filter(each => each !== file)
  record(mission, { type: on ? 'adr.attached' : 'adr.detached', note: plain(file, 120) })
  saveLedger(state, host)
  await mirrorDigest(state, host)
  say(state, host, on ? 'attach ADR' : 'detach ADR', true, [`${file} ${on ? 'attached to' : 'detached from'} the mission`])
  announce(state, host, `ADR ${docOf(state, file)?.number ?? file} ${on ? 'attached to' : 'detached from'} the mission`)
}

/** Where the swarm plugin reads the digest: a small, masked file under the console's own folder. */
export const DIGEST_FILE = '.claude-flow/console/adr-digest.json'

/**
 * Writes (or clears) the digest the swarm plugin appends to a spawned subagent's prompt. Only the active mission's attached ADRs; the
 * text is the same masked, capped block Claude reads. Never throws.
 */
export async function mirrorDigest(state: State, host: Pick<Host, 'fs' | 'run'>): Promise<string | null> {
  const mission = activeMission(state)
  const docs = mission === null ? [] : attachedDocs(state, mission)
  const body = JSON.stringify({ v: 1, atMs: Date.now(), mission: mission?.id ?? '', adrs: docs.slice(0, MAX_ATTACH).map(doc => ({ number: doc.number, file: doc.file, status: doc.status })), block: digestBlock(docs) })

  return replaceFile(host, state.cwd, `${root(state)}/${DIGEST_FILE}`, body)
}

const mirrored = new WeakMap<State, string>()

/**
 * Keeps the swarm's digest file true to the ACTIVE mission, called from the controller's tick and cheap when nothing moved: it writes only
 * when the active mission or the text of its digest changed, writes an empty digest (which the swarm treats as none) when nothing is
 * attached, and clears a file an earlier session left behind. It never creates a file in a project that has never attached an ADR, and it
 * does not judge before the folder has been read (an unread registry would look like "nothing attached").
 */
export async function syncAdrDigest(state: State, host: Host): Promise<void> {
  const mission = activeMission(state)
  const attached = mission === null ? [] : attachedOf(mission)
  const adr = adrOf(state)

  if (attached.length > 0 && !adr.isLoaded) {
    if (!adr.isLoading) void loadAdrs(state, host)

    return
  }

  const block = mission === null ? '' : digestBlock(attachedDocs(state, mission))
  const key = `${mission?.id ?? ''}|${block}`
  const before = mirrored.get(state)

  if (before === key) return

  mirrored.set(state, key)

  // The first look of a session at an empty digest only matters if an earlier session left a non-empty file.
  if (before === undefined && block === '') {
    const stat = await host.fs.stat(`${root(state)}/${DIGEST_FILE}`).catch(() => undefined)

    if (stat === undefined) return
  }

  // A failed write is tried again on the next tick.
  if ((await mirrorDigest(state, host)) !== null) mirrored.delete(state)
}

/** Files changed in the project: uncommitted work, and commits since the mission began. Read-only git. */
export async function changedFiles(host: Pick<Host, 'run'>, cwd: string, sinceMs: number): Promise<string[]> {
  const out = new Set<string>()
  const status = await host.run(['git', '-C', cwd, 'status', '--porcelain'], 15_000).catch(() => null)

  for (const line of (status?.stdout ?? '').split('\n')) {
    const path = line.slice(3).split(' -> ').pop()?.trim().replace(/^"|"$/g, '')

    if (path !== undefined && path !== '') out.add(path)
  }

  const log = await host.run(['git', '-C', cwd, 'log', `--since=${new Date(Math.max(0, sinceMs)).toISOString()}`, '--name-only', '--pretty=format:'], 15_000).catch(() => null)

  for (const line of (log?.stdout ?? '').split('\n')) if (line.trim() !== '') out.add(line.trim())

  return [...out].slice(0, 400)
}

/** The scope check for the active mission: a warning per accepted ADR whose paths a changed file falls under. Recorded as mission evidence; blocks nothing. */
export async function scopeCheck(state: State, host: Pick<Host, 'run' | 'invalidate'>): Promise<string[]> {
  const mission = activeMission(state)

  if (mission === null) return ['no active mission']

  const docs = attachedDocs(state, mission)
  const report = checkScope(docs.length === 0 ? [] : await changedFiles(host, state.cwd, mission.createdAtMs), docs)
  const lines = reportLines(report)

  adrOf(state).scope = report
  if (docs.length > 0) record(mission, { type: 'adr.scope', note: plain(lines.join(' | '), 400) })
  host.invalidate()

  return lines
}

/** A draft record for the active mission, as a proposeSpec: only the mission's own words; a person writes the decision. */
export function draftSpec(state: State, host: Pick<Host, 'fs' | 'run' | 'invalidate' | 'toast'>, today: string): ActionSpec | null {
  const mission = activeMission(state)

  if (mission === null) return null

  const finished = mission.events.filter(event => event.type === 'task.complete' || event.status === 'done')
  const results = new Map<string, string>(finished.flatMap(event => (event.taskId !== undefined && event.note !== undefined ? [[event.taskId, event.note] as [string, string]] : [])))
  const draft = draftFromMission({ objective: mission.objective, tasks: mission.tasks.map(task => ({ title: task.title, ...(results.has(task.id) && { result: results.get(task.id) as string }) })) }, attachedDocs(state, mission).flatMap(doc => doc.scope.slice(0, 2)), today)

  const spec = proposeSpec(state, host, draft.title, today, { ...(draft.context !== undefined && { context: draft.context }), ...(draft.decision !== undefined && { decision: draft.decision }), scope: draft.scope ?? [] })

  // A title is one line; an objective can be a paragraph. When it was shortened, the confirm says so and by how much (ADR-481).
  if (spec === null || draft.titleShortenedFrom === undefined) return spec

  const said = `The title was shortened from the mission's objective: ${draft.titleShortenedFrom} → ${Array.from(draft.title).length} characters; the full objective is in the record's Context.`

  return { ...spec, note: `${said} ${spec.note ?? ''}`.trim() }
}

files.hooks/data/sessions-index.ts:
/**
 * The session workspace's index (ADR-486): the adapters' rows merged into one list, each with an identity that cannot be mistaken for
 * another's. Identity is harness + canonical home + native id. A row whose id is claimed by more than one file, or whose entries name another
 * id, is UNASSIGNED: it is listed in its own bucket, shows no preview, and never raises an attention item, because the one thing this page must
 * not do is show one session's output under another's name. Grouping is by repository, then worktree, from the recorded cwd's path alone.
 */
import { HARNESS_IDS, type Capabilities, type HarnessId, type ScanResult, type SessionRow } from './harness'

export type HarnessReport = { id: HarnessId; label: string; state: ScanResult['state']; note: string; count: number; capabilities: Capabilities }
export type Group = { label: string; repo: string; unassigned: boolean; rows: SessionRow[] }
export type Index = { rows: SessionRow[]; groups: Group[]; reports: HarnessReport[]; unassigned: number; builtAtMs: number }
export type Scanned = { id: HarnessId; label: string; capabilities: Capabilities; result: ScanResult }

const SEVERITY: Record<SessionRow['status'], number> = { failed: 0, working: 1, idle: 2, done: 3, unknown: 4 }

/** The last two path segments, so a long path stays recognisable in a group heading. */
export const shortRepo = (repo: string): string => {
  const parts = repo.split('/').filter(part => part !== '')

  return parts.length <= 2 ? repo : `…/${parts.slice(-2).join('/')}`
}

export function buildIndex(scans: readonly Scanned[], own: ReadonlySet<string>, nowMs: number): Index {
  const all = scans.flatMap(scan => scan.result.rows)
  const seen = new Map<string, number>()

  for (const row of all) seen.set(row.key, (seen.get(row.key) ?? 0) + 1)

  const rows: SessionRow[] = all.map((row, i) => {
    const copies = seen.get(row.key) ?? 1
    // A duplicated id gets a key of its own, so selecting one copy can never select (or show) the other.
    const key = copies > 1 ? `${row.key}~${row.folder}~${i}` : row.key
    const unassigned = copies > 1 ? `the id is claimed by ${copies} files` : row.unassigned

    return { ...row, key, unassigned, external: row.harness === 'ruflo' ? false : !own.has(row.nativeId), ...(unassigned !== null && { preview: null, noPreview: 'unassigned: not shown', title: `${row.harness} file ${row.nativeId.slice(0, 8)} in ${row.folder}`, cwd: null, branch: null, context: [] }) }
  })

  const groups = new Map<string, Group>()

  for (const row of rows) {
    const bucket = row.unassigned !== null
    const id = bucket ? '\u0000unassigned' : `${row.repo}\u0000${row.worktree ?? ''}`
    const held = groups.get(id) ?? { label: bucket ? 'unassigned' : `${shortRepo(row.repo)}${row.worktree === null ? '' : ` › ${row.worktree}`}`, repo: row.repo, unassigned: bucket, rows: [] }

    held.rows.push(row)
    groups.set(id, held)
  }

  const ordered = [...groups.values()].map(group => ({ ...group, rows: group.rows.sort((a, b) => SEVERITY[a.status] - SEVERITY[b.status] || b.updatedMs - a.updatedMs) }))

  ordered.sort((a, b) => Number(a.unassigned) - Number(b.unassigned) || Math.max(...b.rows.map(r => r.updatedMs)) - Math.max(...a.rows.map(r => r.updatedMs)))

  return {
    rows,
    groups: ordered,
    unassigned: rows.filter(row => row.unassigned !== null).length,
    builtAtMs: nowMs,
    reports: HARNESS_IDS.map(id => scans.find(scan => scan.id === id)).flatMap(scan => (scan === undefined ? [] : [{ id: scan.id, label: scan.label, state: scan.result.state, note: scan.result.note, count: scan.result.rows.length, capabilities: scan.capabilities }])),
  }
}

/** The row with this key, or undefined: the only lookup the preview uses, so a selection can only ever resolve to the row it names. */
export const rowOf = (index: Index | null, key: string | null): SessionRow | undefined => (index === null || key === null ? undefined : index.rows.find(row => row.key === key))

files.hooks/data/sessions-attention.ts:
/**
 * The attention queue (ADR-486): what needs the person, across every harness. Four kinds, in this order: needs-approval, question, failed,
 * completed-unread. An approval or a question stays until the harness stops reporting it (viewing never clears one). A failure or a completion
 * clears once its content was actually displayed (`markViewed`, committed by the page after the frame that drew the preview), and comes back
 * only if the session moves on to something newer. Completions older than the baseline (when this queue first ran) are history, not unread.
 * An unassigned row raises nothing: its identity is in doubt.
 */
import { ATTENTION_KINDS, type AttentionKind, type SessionRow } from './harness'

export type Viewed = { baselineMs: number; seen: Record<string, number> }
export const SEEN_MAX = 500

export type AttentionItem = { id: string; kind: AttentionKind; rowKey: string | null; title: string; harness: string; atMs: number; detail: string; stale: boolean }
export type PendingAsk = { label: string; askedAtMs: number } | null

const DETAIL: Record<AttentionKind, string> = { 'needs-approval': 'waiting for your yes', question: 'asked you a question', failed: 'the last tool failed', 'completed-unread': 'finished since you looked' }

export const newViewed = (nowMs: number): Viewed => ({ baselineMs: nowMs, seen: {} })

/** A stored value read back: anything not shaped like a Viewed is a fresh one, never trusted. */
export function viewedOf(raw: unknown, nowMs: number): Viewed {
  if (typeof raw !== 'object' || raw === null) return newViewed(nowMs)

  const value = raw as { baselineMs?: unknown; seen?: unknown }
  const seen: Record<string, number> = {}

  if (typeof value.seen === 'object' && value.seen !== null) {
    for (const [key, stamp] of Object.entries(value.seen).slice(0, SEEN_MAX)) if (typeof stamp === 'number' && Number.isFinite(stamp)) seen[key.slice(0, 300)] = stamp
  }

  return { baselineMs: typeof value.baselineMs === 'number' && Number.isFinite(value.baselineMs) ? value.baselineMs : nowMs, seen }
}

const seenKey = (rowKey: string, kind: AttentionKind) => `${rowKey}|${kind}`

export function attentionOf(rows: readonly SessionRow[], viewed: Viewed, pending: PendingAsk): AttentionItem[] {
  const items: AttentionItem[] = []

  if (pending !== null) items.push({ id: 'console:pending', kind: 'needs-approval', rowKey: null, title: pending.label, harness: 'console', atMs: pending.askedAtMs, detail: 'a confirm is waiting for your yes', stale: false })

  for (const row of rows) {
    if (row.unassigned !== null) continue

    const add = (kind: AttentionKind, atMs: number) => items.push({ id: seenKey(row.key, kind), kind, rowKey: row.key, title: row.title, harness: row.harness, atMs, detail: DETAIL[kind], stale: row.stale !== null })

    if (row.signals.approval) add('needs-approval', row.updatedMs)
    if (row.signals.question) add('question', row.updatedMs)
    if (row.signals.failed && Math.max(1, row.updatedMs) > (viewed.seen[seenKey(row.key, 'failed')] ?? 0)) add('failed', Math.max(1, row.updatedMs))

    const ended = row.signals.turnEndedAtMs

    if (ended !== null && ended >= viewed.baselineMs && ended > (viewed.seen[seenKey(row.key, 'completed-unread')] ?? 0) && !row.signals.question) add('completed-unread', ended)
  }

  return items.sort((a, b) => ATTENTION_KINDS.indexOf(a.kind) - ATTENTION_KINDS.indexOf(b.kind) || b.atMs - a.atMs)
}

/** Records that the content of these items was displayed. Approvals and questions are not recorded: only the harness resolves them. */
export function markViewed(viewed: Viewed, items: readonly AttentionItem[]): Viewed {
  const seen = { ...viewed.seen }
  let changed = false

  for (const item of items) {
    if (item.rowKey === null || (item.kind !== 'failed' && item.kind !== 'completed-unread')) continue
    if ((seen[item.id] ?? 0) >= item.atMs) continue

    seen[item.id] = item.atMs
    changed = true
  }

  if (!changed) return viewed

  const kept = Object.entries(seen).sort((a, b) => b[1] - a[1]).slice(0, SEEN_MAX)

  return { baselineMs: viewed.baselineMs, seen: Object.fromEntries(kept) }
}

export const countsOf = (items: readonly AttentionItem[]): Record<AttentionKind, number> => ({
  'needs-approval': items.filter(item => item.kind === 'needs-approval').length,
  question: items.filter(item => item.kind === 'question').length,
  failed: items.filter(item => item.kind === 'failed').length,
  'completed-unread': items.filter(item => item.kind === 'completed-unread').length,
})

