/**
 * The `ruflo` worker adapter (ADR-486): what the console already knows without reading a transcript. A mission as the CLI observed it
 * (`.claude-flow/missions/observation.json`, ADR-406) and the agents the swarm and hive stores list. Nothing is read from disk here;
 * a state the observation does not record is not invented. `awaitingAuthorization` is the one state that means "waiting for a yes".
 */
import { no, yes, type Capabilities, type HarnessAdapter, type ScanEnv, type ScanResult, type SessionRow, type SessionStatus } from './harness'
import type { Mission, MissionObservation } from './missions'
import type { AgentRecord } from './parse'
import { shown } from './harness-text'

export const RUFLO_CAPS: Capabilities = {
  discovery: yes('the mission observation and the agent stores the console already reads'),
  preview: yes('state, task and evidence counts; there is no transcript to show'),
  approvals: yes('a mission in awaitingAuthorization is waiting for a yes'),
  resume: no('missions are driven from the Missions page'),
  fork: no('not in phase 1'),
  messaging: no('broadcast and guide stay on the Room and Missions pages, each asking first'),
  stop: no('pause and cancel stay on the Missions page, each asking first'),
}

/** What the console's own mission ledger and claims add to an observed mission, by mission id; each is shown only when it holds something. */
export type LedgerFacts = { adrs?: readonly string[]; tasks: readonly { id: string; dependsOn: readonly string[]; rufloTaskId?: string }[] }
export type RufloInput = { cwd: string; missions: MissionObservation | null; agents: readonly AgentRecord[]; nowMs: number; ledger?: ReadonlyMap<string, LedgerFacts>; claimedIssues?: ReadonlySet<string> }

function contextOf(mission: Mission, input: RufloInput): string[] {
  const lines: string[] = []
  const facts = input.ledger?.get(mission.id)
  const active = mission.plan.tasks.find(task => task.status === 'running' || task.status === 'inProgress' || task.status === 'in_progress')

  if (active !== undefined) lines.push(`task ${shown(active.id, 30)}: ${shown(active.title, 80)}${active.dependsOn.length === 0 ? '' : ` · after ${active.dependsOn.slice(0, 4).map(dep => shown(dep, 20)).join(', ')}`}`)
  if (facts !== undefined) {
    const claimed = facts.tasks.filter(task => input.claimedIssues?.has(task.id) === true || (task.rufloTaskId !== undefined && input.claimedIssues?.has(task.rufloTaskId) === true)).length

    if (claimed > 0) lines.push(`claims: ${claimed} of this mission's tasks are claimed`)
    if ((facts.adrs ?? []).length > 0) lines.push(`ADRs: ${(facts.adrs ?? []).slice(0, 4).map(adr => shown(adr, 50)).join(', ')}`)
  }

  if (mission.evidence.count > 0) lines.push(`verification: ${mission.evidence.verified} of ${mission.evidence.count} evidence verified`)

  return lines
}

const MISSION_STATUS: Record<string, SessionStatus> = { running: 'working', verifying: 'working', queued: 'working', completed: 'done', failed: 'failed' }
const AGENT_BAD = /^(?:failed|error|crashed|dead)$/i
const AGENT_BUSY = /^(?:busy|working|running|active)$/i

const costOf = (mission: Mission): SessionRow['cost'] => {
  const budget = mission.budget

  if (budget === null) return { label: 'unavailable', note: 'the mission records no budget' }
  if (budget.settledMinor !== undefined) return budget.currency === 'USD' ? { label: 'reported', usd: budget.settledMinor / 100 } : { label: 'reported', note: `${budget.currency} ${budget.settledMinor} minor units` }
  if (budget.estimatedMinor !== undefined) return budget.currency === 'USD' ? { label: 'estimated', usd: budget.estimatedMinor / 100 } : { label: 'estimated', note: `${budget.currency} ${budget.estimatedMinor} minor units` }

  return { label: 'unavailable', note: 'the mission records no spend' }
}

export function rufloRows(input: RufloInput): SessionRow[] {
  const home = 'ruflo'
  const rows: SessionRow[] = []

  for (const mission of input.missions?.missions ?? []) {
    const tasks = mission.plan.tasks
    const done = tasks.filter(task => task.status === 'completed' || task.status === 'done').length

    rows.push({
      key: `ruflo:${home}:mission-${mission.id}`,
      harness: 'ruflo',
      home,
      nativeId: `mission-${mission.id}`,
      title: shown(mission.objective, 80) || mission.id,
      status: MISSION_STATUS[mission.state] ?? 'idle',
      cwd: input.cwd,
      folder: 'missions',
      repo: input.cwd,
      worktree: null,
      branch: null,
      mission: mission.id,
      updatedMs: mission.updatedAtMs ?? input.missions?.observedAtMs ?? 0,
      size: 0,
      unassigned: null,
      stale: null,
      external: false,
      cost: costOf(mission),
      signals: { question: false, approval: mission.state === 'awaitingAuthorization', failed: mission.state === 'failed', turnEndedAtMs: mission.state === 'completed' ? (mission.updatedAtMs ?? null) : null },
      context: contextOf(mission, input),
      preview: { latest: `${mission.state}${mission.blockedReason === undefined ? '' : `: ${shown(mission.blockedReason, 120)}`} · ${done} of ${tasks.length} tasks · ${mission.evidence.verified} of ${mission.evidence.count} evidence verified`, tool: null, files: [], test: mission.evidence.count === 0 ? null : `${mission.evidence.verified} of ${mission.evidence.count} verified` },
      noPreview: null,
    })
  }

  for (const agent of input.agents.slice(0, 40)) {
    const name = shown(agent.name ?? agent.id, 40)

    rows.push({
      key: `ruflo:${home}:agent-${agent.id}`,
      harness: 'ruflo',
      home,
      nativeId: `agent-${agent.id}`,
      title: `${name} (${shown(agent.type, 20)})`,
      status: AGENT_BAD.test(agent.status) ? 'failed' : AGENT_BUSY.test(agent.status) ? 'working' : 'idle',
      cwd: input.cwd,
      folder: 'workers',
      repo: input.cwd,
      worktree: null,
      branch: null,
      mission: null,
      updatedMs: agent.createdAtMs ?? 0,
      size: 0,
      unassigned: null,
      stale: null,
      external: false,
      cost: { label: 'unavailable', note: 'the agent store records no spend' },
      signals: { question: false, approval: false, failed: AGENT_BAD.test(agent.status), turnEndedAtMs: null },
      context: [],
      preview: { latest: `${shown(agent.status, 20)}${agent.taskCount === undefined ? '' : ` · ${agent.taskCount} tasks`}`, tool: null, files: [], test: null },
      noPreview: null,
    })
  }

  return rows
}

export function rufloAdapter(input: () => RufloInput): HarnessAdapter {
  return {
    id: 'ruflo',
    label: 'Ruflo workers',
    capabilities: RUFLO_CAPS,
    async scan(_env: ScanEnv): Promise<ScanResult> {
      const rows = rufloRows(input())

      return { state: rows.length === 0 ? 'not-detected' : 'ok', rows, note: rows.length === 0 ? 'no missions or agents recorded' : `${rows.length} missions and workers` }
    },
  }
}

files.hooks/data/harness.ts:
/**
 * The session workspace's adapter contract (ADR-486). A harness adapter finds the sessions one agent harness keeps on this machine and
 * says, per capability, whether it can do that and why not. An action a harness has not declared stays unavailable; nothing is inferred.
 * Discovery is local and read-only: it makes no model call, spawns no process and wakes no agent.
 */
import type { ReaderFs } from './files'

export const HARNESS_IDS = ['claude', 'codex', 'ruflo'] as const
export type HarnessId = (typeof HARNESS_IDS)[number]

/** What an adapter may declare. `approvals`: it can tell that a session is waiting for a yes. */
export const CAPABILITIES = ['discovery', 'preview', 'approvals', 'resume', 'fork', 'messaging', 'stop'] as const
export type Capability = (typeof CAPABILITIES)[number]
export type CapabilityState = { supported: boolean; why: string }
export type Capabilities = Record<Capability, CapabilityState>

export const yes = (why = 'verified against the on-disk format'): CapabilityState => ({ supported: true, why })
export const no = (why: string): CapabilityState => ({ supported: false, why })

/** The four kinds the attention queue shows. */
export const ATTENTION_KINDS = ['needs-approval', 'question', 'failed', 'completed-unread'] as const
export type AttentionKind = (typeof ATTENTION_KINDS)[number]

/** Cost is never guessed: `reported` came from the harness, `estimated` from a stated rule, `unavailable` is shown as such. */
export type Cost = { label: 'reported' | 'estimated' | 'unavailable'; usd?: number; note?: string }

export type Preview = {
  /** The latest response, sanitised and cut. Never model-facing, never persisted, never exported. */
  latest: string
  tool: string | null
  files: string[]
  test: string | null
}

export type Signals = {
  /** A question put to the person is open (the harness asked, nothing has answered). */
  question: boolean
  /** An approval is open (only an adapter that declares `approvals` sets it). */
  approval: boolean
  /** The last tool failed and nothing followed it. */
  failed: boolean
  /** The last turn finished at this time. */
  turnEndedAtMs: number | null
}

export type SessionStatus = 'working' | 'idle' | 'done' | 'failed' | 'unknown'

export type SessionRow = {
  /** Identity: harness + canonical home + native id. Two rows never share one. */
  key: string
  harness: HarnessId
  home: string
  nativeId: string
  title: string
  status: SessionStatus
  /** The working directory the harness recorded, or null when it could not be read (never guessed from the folder name). */
  cwd: string | null
  /** The project folder name the harness keeps this session in; the group label when no cwd is known. */
  folder: string
  repo: string
  worktree: string | null
  branch: string | null
  /** The mission this session is known to belong to, by an exact id the harness recorded; null otherwise. */
  mission: string | null
  updatedMs: number
  size: number
  /** Why this row could not be tied to one session (ambiguous id, id mismatch); it then sits in the unassigned bucket. */
  unassigned: string | null
  /** The last read failed or the window was incomplete: what is shown is from an earlier read or from the tail only. */
  stale: string | null
  /** Started outside Ruflo: nothing in Ruflo launched it. */
  external: boolean
  cost: Cost
  signals: Signals
  preview: Preview | null
  /** Mission context lines (assigned task, dependencies, claims, ADRs, verification): only what the console's own records hold. */
  context: string[]
  /** Why there is no preview (too large for this host, unreadable). */
  noPreview: string | null
}

export type ScanResult = { state: 'ok' | 'not-detected' | 'failed'; rows: SessionRow[]; note: string }

/** What a host can do for a read: `readTail` exists only where the host offers it (ADR-473). */
export type SessionFs = ReaderFs & { readTail?: (path: string, bytes: number) => Promise<string> }

export type ScanEnv = {
  fs: SessionFs
  /** Claude Code's config directory and Codex's home, or null when unknown. */
  claudeDir: string | null
  codexDir: string | null
  nowMs: number
  /** Relist everything (slow pass); otherwise only what changed and the recently active files. */
  full: boolean
}

export interface HarnessAdapter {
  readonly id: HarnessId
  readonly label: string
  readonly capabilities: Capabilities
  scan(env: ScanEnv): Promise<ScanResult>
}

/** Splits a recorded cwd into its repository and worktree by path alone (no git, no disk): `<repo>/.claude/worktrees/<name>` and its kin. */
export function repoOf(cwd: string): { repo: string; worktree: string | null } {
  const marker = /^(.*?)\/(?:\.claude\/worktrees|\.git-worktrees|\.worktrees)\/([^/]+)/.exec(cwd)

  return marker !== null && marker[1] !== undefined && marker[2] !== undefined ? { repo: marker[1] === '' ? '/' : marker[1], worktree: marker[2] } : { repo: cwd, worktree: null }
}

files.hooks/activity-io.ts:
/**
 * The one write path for the Events and Timeline files (ADR-474), with the host's `fs` and `run` passed in so a test supplies its own.
 * Lines are queued in memory and written in batches (never one write per event): at most one write per file is in flight, each batch
 * is at most BATCH_MAX bytes, and a failure is remembered and retried later, never thrown. A write appends through the journal's fixed
 * argv (data/append-argv.ts: GNU `dd oflag=append` with no shell on Linux, a constant `sh -c` script with the path as `$1` on macOS/BSD; the
 * path is one element either way, and one dd block per batch into an O_APPEND file keeps two consoles' batches apart unless a write is split). A file past its cap is cut to its newest half through a temporary file and a rename.
 * The folder is created once, and nothing is written through a link.
 */
import { checkNoLinks } from './data/wf-file'
import { appendArgv } from './data/append-argv'
import { dirOf, newFileArgv, replaceFileArgv } from './data/wf-file'
import { writeFlavorReady } from './data/write-flavor'
import { keepNewestHalf, READ_MAX } from './data/activity-store'
import type { Host } from './host'

export type IoHost = Pick<Host, 'fs' | 'run'>

export const BATCH_MAX = 32 * 1024

/** The append argv is shared with the autopilot journal (data/append-argv.ts): one block per batch, so two consoles never tear a line. A batch is at most BATCH_MAX plus one line. */
export { appendArgv }

/** The folder's own `.gitignore` (`*`): `.claude-flow/.gitignore` from `ruflo init` does not list `console/`, and these files hold a person's history. */
export const IGNORE_BODY = '# the ruflo console\'s own history: local state, never committed\n*\n'
export const PENDING_MAX = 2_000
export const RETRY_MS = 30_000
const WRITE_TIMEOUT_MS = 10_000

type Channel = { path: string; cap: number; pending: string[]; isWriting: boolean; size: number | null; retryAtMs: number; error: string | null; isDirReady: boolean; clearAtMs: number; writes: number; rotations: number }

const channels = new Map<string, Channel>()
const ignored = new Set<string>()

export const channelOf = (path: string, cap: number): Channel => {
  const found = channels.get(path)

  if (found !== undefined) return found

  const made: Channel = { path, cap, pending: [], isWriting: false, size: null, retryAtMs: 0, error: null, isDirReady: false, clearAtMs: 0, writes: 0, rotations: 0 }

  channels.set(path, made)

  return made
}

/** For tests: forgets every channel. */
export const resetIo = (): void => {
  channels.clear()
  ignored.clear()
}

/** Queues one line; the oldest queued lines go when a failing disk lets the queue grow past PENDING_MAX. */
export function queueLine(path: string, cap: number, line: string): void {
  const channel = channelOf(path, cap)

  channel.pending.push(line)
  if (channel.pending.length > PENDING_MAX) channel.pending.splice(0, channel.pending.length - PENDING_MAX)
}

export const pendingOf = (path: string): number => channels.get(path)?.pending.length ?? 0
export const errorOf = (path: string): string | null => channels.get(path)?.error ?? null
export const forgetChannel = (path: string): void => void channels.delete(path)

const tmpOf = (path: string): string => `${path}.tmp`

/** Writes `<dir>/.gitignore` once per folder if there is none (the exclusive create fails, harmlessly, where one exists). Never throws. */
async function ensureIgnored(host: IoHost, dir: string): Promise<void> {
  if (ignored.has(dir)) return

  ignored.add(dir)
  await host.run(newFileArgv(`${dir}/.gitignore`, true, await writeFlavorReady()), WRITE_TIMEOUT_MS, IGNORE_BODY).catch(() => undefined)
}

async function rotate(host: IoHost, channel: Channel): Promise<void> {
  const stat = await host.fs.stat(channel.path).catch(() => undefined)

  if (stat === undefined) return

  const size = stat.size ?? channel.size ?? 0
  const kept = size > READ_MAX ? '' : keepNewestHalf(await host.fs.read(channel.path).catch(() => ''), channel.cap)
  await host.run(['rm', '-f', '--', tmpOf(channel.path)], WRITE_TIMEOUT_MS)

  // The flavor is awaited before the first flavored write; the rm, mv and mkdir argv are the same on GNU and BSD, so they need none.
  const written = await host.run(newFileArgv(tmpOf(channel.path), true, await writeFlavorReady()), WRITE_TIMEOUT_MS, kept)

  if (written.exitCode !== 0) return

  const moved = await host.run(['mv', '-f', '--', tmpOf(channel.path), channel.path], WRITE_TIMEOUT_MS)

  if (moved.exitCode === 0) {
    channel.size = kept.length
    channel.rotations++
  }
}

/** One pass for one file: writes what is queued if nothing is in flight and no recent failure is waiting out. Never throws. */
export async function flush(host: IoHost, cwd: string, path: string, nowMs: number = Date.now()): Promise<void> {
  const channel = channels.get(path)

  if (channel === undefined || channel.pending.length === 0 || channel.isWriting || nowMs < channel.retryAtMs) return

  channel.isWriting = true

  const batch: string[] = []
  let bytes = 0

  while (channel.pending.length > 0 && bytes + (channel.pending[0] as string).length <= BATCH_MAX) {
    const line = channel.pending.shift() as string

    batch.push(line)
    bytes += line.length
  }

  if (batch.length === 0) batch.push(channel.pending.shift() as string)

  try {
    const clear = await checkNoLinks(host.fs, path, { cwd: cwd.replace(/\/+$/, '') }, { allowExisting: true })

    if (!clear.ok) throw new Error(clear.why)

    if (!channel.isDirReady) {
      const made = await host.run(['mkdir', '-p', '--', dirOf(path)], WRITE_TIMEOUT_MS)

      if (made.exitCode !== 0) throw new Error(`the folder could not be made (exit ${made.exitCode})`)
      channel.isDirReady = true
    }

    await ensureIgnored(host, dirOf(path))

    if (channel.size === null) channel.size = (await host.fs.stat(path).catch(() => undefined))?.size ?? 0

    const result = await host.run(appendArgv(path, await writeFlavorReady()), WRITE_TIMEOUT_MS, batch.join(''))

    if (result.exitCode !== 0) throw new Error(`the write exited ${result.exitCode}`)

    channel.size += bytes
    channel.writes++
    channel.error = null

    if (channel.size > channel.cap) await rotate(host, channel)
  } catch (error) {
    channel.pending.unshift(...batch)
    channel.error = (error instanceof Error ? error.message : 'the write was refused').slice(0, 80)
    channel.retryAtMs = nowMs + RETRY_MS
  } finally {
    channel.isWriting = false
  }
}

/** Replaces a small state file whole (the prefs): checked for links, written in place. Returns the problem, or null. */
export async function replaceFile(host: IoHost, cwd: string, path: string, content: string): Promise<string | null> {
  try {
    const clear = await checkNoLinks(host.fs, path, { cwd: cwd.replace(/\/+$/, '') }, { allowExisting: true })

    if (!clear.ok) return clear.why.slice(0, 80)

    const hasDir = (await host.fs.stat(dirOf(path)).catch(() => undefined)) !== undefined
    const result = await host.run(replaceFileArgv(path, hasDir, await writeFlavorReady()), WRITE_TIMEOUT_MS, content)

    if (result.exitCode === 0) await ensureIgnored(host, dirOf(path))

    return result.exitCode === 0 ? null : `the write exited ${result.exitCode}`
  } catch (error) {
    return error instanceof Error ? error.message.slice(0, 80) : 'the write was refused'
  }
}

files.hooks/data/safe.ts:
/**
 * Values from files and CLI answers that another process wrote: a time past what `Date` holds, a negative, fractional-hostile or infinite
 * count, a ratio outside 0..1. Each helper answers undefined (or text) for what it will not draw, and none throws (#3817). A leaf: no imports.
 */

/** The edge of what `Date` can hold: a time past it makes `toISOString()` throw, so no reader keeps one (#3817). */
export const MAX_TIME_MS = 8.64e15
/** The largest count any view draws: a hostile 1e300 is clamped, never a display value. */
export const MAX_COUNT = 1e12

/** A time in epoch milliseconds that `Date` can hold, else undefined. */
export const timeOf = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) && Math.abs(value) <= MAX_TIME_MS ? value : undefined)

/** A time as ISO text, clamped to `Date`'s range; 'n/a' for anything that is not a finite number. It never throws. */
export const isoOf = (value: unknown): string => (typeof value === 'number' && Number.isFinite(value) ? new Date(Math.min(MAX_TIME_MS, Math.max(-MAX_TIME_MS, value))).toISOString() : 'n/a')

/** A whole, non-negative count capped at MAX_COUNT, else undefined (a negative, fractional-hostile, NaN or infinite value is not a count). */
export const countOf = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) && value >= 0 ? Math.min(Math.floor(value), MAX_COUNT) : undefined)

/** A ratio clamped to 0..1, else undefined. */
export const ratioOf = (value: unknown): number | undefined => (typeof value === 'number' && Number.isFinite(value) ? Math.min(1, Math.max(0, value)) : undefined)

/** A value keyed by a name a file or the CLI supplied: an OWN key only, so `toString`, `constructor` or `__proto__` read as absent, never as a function. */
export const own = <T>(record: Readonly<Record<string, T>>, key: unknown): T | undefined => (typeof key === 'string' && Object.hasOwn(record, key) ? record[key] : undefined)

/** 2000-01-01T00:00:00Z: no ruflo file was written before it. */
const EARLIEST_MS = 946_684_800_000
/** How far ahead of now a write time may be (a clock a little ahead) before it is not believed. */
const FUTURE_SLACK_MS = 86_400_000

/**
 * A write time fit to say "N ago" about: from 2000 to a day past now, else undefined (shown as n/a). timeOf alone admits ±8.64e15, which read
 * "100020735d ago", and a time in the future, which read "0s ago".
 */
export const sinceOf = (ms: number | null | undefined, nowMs: number): number | undefined =>
  typeof ms === 'number' && Number.isFinite(ms) && ms >= EARLIEST_MS && ms <= nowMs + FUTURE_SLACK_MS ? ms : undefined

files.hooks/commands.ts:
/**
 * `/ruflo`, the one command for every ruflo mod. Pure: it reads the arguments into an intent; register.ts carries it
 * out. `mods` and `swarm <sub>` belong to ruflo-mods and ruflo-swarm, which hook the same command; the console passes
 * them on and answers only when neither is loaded. Every pane key has a subcommand here, since keys need focus.
 */
import { EVENT_KINDS, type EventKind } from './data/events'
import { VIEWS, viewOf, type ViewId } from './state'

export const SWARM_SUBS = ['pane', 'status', 'topology', 'claims', 'consensus'] as const

export type Intent =
  | { kind: 'open'; view: ViewId | null }
  | { kind: 'help' }
  | { kind: 'close' }
  | { kind: 'status' }
  | { kind: 'delegate'; owner: 'ruflo-mods' | 'ruflo-swarm'; words: string }
  | { kind: 'palette'; query: string }
  | { kind: 'run'; paletteId: string; text: string }
  | { kind: 'confirm'; isYes: boolean }
  | { kind: 'agent'; who: string }
  | { kind: 'back' }
  | { kind: 'select'; by: number }
  | { kind: 'filter'; filter: 'all' | EventKind }
  | { kind: 'dump'; view: ViewId | null }
  | { kind: 'commands'; query: string }
  | { kind: 'band'; arg: string }
  | { kind: 'notices'; isClear: boolean }
  | { kind: 'quiet'; arg: string }
  | { kind: 'autopilot'; arg: string }
  | { kind: 'events'; args: string[] }
  | { kind: 'timeline'; args: string[] }
  | { kind: 'unknown'; word: string }

export function parseRuflo(args: string): Intent {
  const words = args.trim().split(/\s+/).filter(Boolean)
  const [head = '', second = ''] = words.map(word => word.toLowerCase())
  const rest = args.trim().slice(words[0]?.length ?? 0).trim()

  switch (head) {
    case '':
    case 'open':
      return { kind: 'open', view: null }
    case 'help':
    case '?':
      return { kind: 'help' }
    case 'close':
      return { kind: 'close' }
    case 'status':
      return { kind: 'status' }
    case 'mods':
      return { kind: 'delegate', owner: 'ruflo-mods', words: rest }
    case 'swarm':
      return (SWARM_SUBS as readonly string[]).includes(second) ? { kind: 'delegate', owner: 'ruflo-swarm', words: rest } : { kind: 'open', view: 'swarm' }
    case 'palette':
    case 'p':
      return { kind: 'palette', query: rest }
    // `/ruflo plan <goal>` prints the SPARC plan; `/ruflo mission [status|next|pause|resume|cancel|create|guide <text>|aside <text>|auto on|off]`.
    // `/ruflo ask <question>`: ask the main Claude about the open section (asks first).
    case 'ask':
      return { kind: 'run', paletteId: 'ask', text: rest }
    case 'plan':
      return { kind: 'run', paletteId: 'mission-goal', text: rest }
    case 'mission':
      return { kind: 'run', paletteId: `mission-${second === '' ? 'status' : second.replace(/[^a-z-]/g, '')}`, text: rest.slice(second.length).trim() }
    case 'run':
    case 'act':
      return second === '' ? { kind: 'palette', query: '' } : { kind: 'run', paletteId: second, text: rest.slice(second.length).trim() }
    case 'yes':
    case 'y':
      return { kind: 'confirm', isYes: true }
    case 'no':
    case 'n':
      return { kind: 'confirm', isYes: false }
    case 'agent':
      return second === '' ? { kind: 'open', view: 'swarm' } : { kind: 'agent', who: words[1] ?? '' }
    case 'back':
      return { kind: 'back' }
    case 'next':
    case 'j':
      return { kind: 'select', by: 1 }
    case 'prev':
    case 'k':
      return { kind: 'select', by: -1 }
    case 'band':
      return { kind: 'band', arg: second }
    case 'notices':
      return { kind: 'notices', isClear: second === 'clear' }
    case 'quiet':
      return { kind: 'quiet', arg: second }
    case 'autopilot':
      return { kind: 'autopilot', arg: second }
    case 'commands':
    case 'catalog':
      return { kind: 'commands', query: rest }
    case 'dump':
    case 'text':
      return { kind: 'dump', view: second === '' ? null : viewOf(second) }
    // `/ruflo events [kind|level|since:15m|"query"|window <w>|clear|forget|export <path>|follow <ref>|pin|rule]` and `/ruflo timeline [5m|…|session|zoom in|out|follow <ref>|export <path>]` (ADR-474); bare, each just opens its page.
    case 'events':
      return words.length === 1 ? { kind: 'open', view: 'events' } : { kind: 'events', args: words.slice(1) }
    case 'timeline':
      return words.length === 1 ? { kind: 'open', view: 'timeline' } : { kind: 'timeline', args: words.slice(1) }
    case 'filter':
      return { kind: 'filter', filter: (EVENT_KINDS as readonly string[]).includes(second) ? (second as EventKind) : 'all' }
    default: {
      const view = viewOf(head)

      return view !== null ? { kind: 'open', view } : { kind: 'unknown', word: head }
    }
  }
}

export const HELP = [
  '/ruflo — the ruflo console and every ruflo mod command',
  '',
  'Open and switch',
  `  /ruflo                     open the cockpit (also opens by itself where it can dock, panel=auto)`,
  `  /ruflo <view>              ${VIEWS.map(view => (view.key === '' ? view.id : `${view.id} (${view.key})`)).join(', ')}`,
  '  /ruflo agent <id|name>     drill into one agent: role, task, claims, activity, logs, timeline',
  '  /ruflo back | close | status',
  '  /ruflo dump <view>         a view as plain text, without the pane (for claude -p and scripts)',
  '  /ruflo commands [word]     browse the ruflo command catalog (ADR-406): every command, who owns it, how it runs',
  '',
  'The band above the prompt',
  '  /ruflo band [auto|on|off|compact|full|reset]   show, hide or shrink the band for this session (compact = one row)',
  '  /ruflo notices [clear]     the last ten announcements (approvals, alerts, a mission finishing, a long turn ending, Anatole blocking a call)',
  '  /ruflo quiet [minutes|off] silence the band\'s notice row for a while; notices are still recorded',
  '  /ruflo autopilot [status|pause|resume|stop]   the mission autopilot (ADR-466); it never starts one: Start is on the Workflows page and asks first',
  '',
  'Act (each change asks to confirm; /ruflo yes or /ruflo no answers without focus)',
  '  /ruflo palette [query]     the command palette (key p): spawn, claims, swarm, votes, workers, memory',
  '  /ruflo run <entry> [text]  run a palette entry by id, e.g. run spawn-coder, run route fix the login bug',
  '  /ruflo next | prev         move the selection (keys j / k)',
  '  /ruflo filter <kind>       events view filter: all, swarm, claims, federation, learning, tools, mods, missions, workflows, autopilot, anatole, notices',
  '  /ruflo events [kind|level|since:15m|"query"|window <session|15m|1h|24h|all>|clear|forget|export <path>|follow <ref>|pin|rule]',
  '                             the Events page: filter, search (words "phrase" -not kind:x level:bad agent:x src:x since:1h a|b /re/), follow an agent, claim or run, export, forget the kept history',
  '  /ruflo timeline [5m|15m|1h|6h|24h|session|zoom <in|out>|follow <ref>|export <path>]   the Timeline page window, zoom, a lane\'s events, a lane summary export',
  '',
  'Other mods (answered by their own plugin)',
  '  /ruflo mods                ruflo-mods: what this session routed, recorded and tightened (was /ruflo-mods)',
  '  /ruflo swarm pane|status|topology|claims|consensus   ruflo-swarm (was /ruflo-swarm-*)',
  '',
  'Pane keys (while it holds the keyboard: /ruflo opens it with the keys, or click it; ctrl+x tab reaches the band, not the pane)',
