/** The session workspace's two options (ADR-486), read the way every other option family is: a value the plugin does not know is its default. */
export type SessionOptions = {
  /** The attention queue and session browser on the Room. Read-only discovery; on by default. */
  sessionWorkspace: boolean
  /** The preview beside the list. Off draws no transcript text at all. */
  sessionPreview: boolean
}

export const sessionOptionsOf = (raw: unknown): SessionOptions => {
  const value = (typeof raw === 'object' && raw !== null ? raw : {}) as Record<string, unknown>
  const on = (v: unknown): boolean => v !== false && v !== 'false'

  return { sessionWorkspace: on(value.sessionWorkspace), sessionPreview: on(value.sessionPreview) }
}

files.hooks/data/wf-targets.ts:
/**
 * Who the console can talk to (ADR-465). Pure: what the session and the stores hold, and what the person configured, in; a list of targets
 * out. Every target declares its transport, WHAT LEAVES THE MACHINE, its cost class and HOW A REPLY ARRIVES, so the composer and the confirm
 * card say it before anything is sent. A target that is not configured is not listed as if it were: an absent one is an honest empty state.
 *
 * The configuration is one option string, entries separated by `;` (nothing in it is a secret: a key is named by its environment variable):
 *   endpoint:<name>=<base-url>|<KEY_ENV>|<model>    an OpenAI-compatible chat endpoint (OpenRouter, the meta-llm gateway, a local server)
 *   bbs:<room>                                       an agentbbs room            (federation_bbs_publish / federation_bbs_watch)
 *   x:<channel>                                      an x-federation channel     (pub:<name> or prv:<16 hex>)
 * OpenRouter is always offered as `openrouter` (https://openrouter.ai/api/v1, OPENROUTER_API_KEY) while no entry of that name replaces it.
 */
export type TransportKind = 'prompt' | 'send-message' | 'hive' | 'task' | 'bbs' | 'x-channel' | 'peer' | 'codex' | 'http'
export type Leaves = 'machine' | 'tailnet' | 'internet'
export type CostClass = 'session-turn' | 'free' | 'metered' | 'peer-session' | 'local-cli'
export type Arrival = 'turn' | 'immediate' | 'polled' | 'none'

export type Target = {
  id: string
  label: string
  transport: TransportKind
  /** What leaves this machine, in words. */
  leavesText: string
  leaves: Leaves
  cost: CostClass
  costText: string
  arrival: Arrival
  arrivalText: string
  /** Transport details: an agent id, a peer host, a channel id, an endpoint's name. */
  ref: string
}

/** The one option this feature reads, checked the way ADR-462's guard options are: a non-string is the default (empty), and the text is capped. */
export type ConvoOptions = { convoTargets: string }

export const convoOptionsOf = (raw: unknown): ConvoOptions => {
  const value = (typeof raw === 'object' && raw !== null ? (raw as Record<string, unknown>).convoTargets : undefined) as unknown

  return { convoTargets: typeof value === 'string' ? value.slice(0, 2000) : '' }
}

export type Endpoint = { name: string; baseUrl: string; keyEnv: string; model: string }

export type Config = { endpoints: Endpoint[]; rooms: string[]; channels: string[]; errors: string[] }

export const OPENROUTER: Endpoint = { name: 'openrouter', baseUrl: 'https://openrouter.ai/api/v1', keyEnv: 'OPENROUTER_API_KEY', model: 'openrouter/auto' }

const NAME = /^[a-z][a-z0-9-]{0,23}$/
const ENV_NAME = /^[A-Z_][A-Z0-9_]{0,63}$/
/** Variables that hold credentials for something other than a model endpoint: naming one would send it to whatever host the URL names. */
const NOT_A_MODEL_KEY = /^(AWS_|GH_|GITHUB_|NPM_|SSH_|KUBE|DOCKER|GCLOUD|GOOGLE_APPLICATION|CLOUDFLARE_|FLY_|TAILSCALE_|NPM)|PASSWORD|PRIVATE|SECRET_ACCESS|PASSPHRASE|^HOME$|^PATH$/
const ROOM = /^[A-Za-z0-9][A-Za-z0-9._-]{0,63}$/
const CHANNEL = /^(pub:[a-z0-9][a-z0-9._-]{0,63}|prv:[0-9a-f]{16})$/
const MODEL = /^[A-Za-z0-9][A-Za-z0-9._:/@+-]{0,80}$/
export const HOST = /^[A-Za-z0-9][A-Za-z0-9._-]{0,62}$/

const isTailnetIp = (host: string): boolean => {
  const m = /^100\.(\d{1,3})\.\d{1,3}\.\d{1,3}$/.exec(host)

  return m !== null && Number(m[1]) >= 64 && Number(m[1]) <= 127
}

/** Addresses a request must never be aimed at, whatever the scheme: link-local (the cloud metadata service), the unspecified address, multicast and every IPv6 literal but ::1 (an IPv4-mapped one reaches the same). */
const forbiddenHost = (host: string): boolean => {
  const h = host.toLowerCase().replace(/\.$/, '')

  if (h.startsWith('[')) return h !== '[::1]'

  return /^169\.254\./.test(h) || /^0\./.test(h) || /^(22[4-9]|23\d|24\d|25[0-5])\./.test(h) || h === 'metadata' || h === 'metadata.google.internal' || h.endsWith('.internal') || h.endsWith('.local') || h === 'instance-data'
}

/** True for an http(s) base URL with no credentials, query or fragment in it, not aimed at a link-local, metadata or IPv6-literal host, and only https unless it is this machine or the tailnet (100.64/10, *.ts.net, a bare MagicDNS name). */
export function isBaseUrl(value: string): boolean {
  let url: URL

  try {
    url = new URL(value)
  } catch {
    return false
  }

  if (url.username !== '' || url.password !== '' || url.search !== '' || url.hash !== '') return false
  if (url.protocol !== 'https:' && url.protocol !== 'http:') return false
  if (forbiddenHost(url.hostname)) return false
  if (url.protocol === 'https:') return true

  return /^(localhost|127\.0\.0\.1|\[::1\]|[a-z][a-z0-9-]*|[a-z0-9.-]+\.ts\.net)$/i.test(url.hostname) || isTailnetIp(url.hostname)
}

/** The option string as targets: each bad entry is dropped with a reason (never thrown), so one typo does not hide the rest. */
export function parseConfig(value: string | undefined): Config {
  const config: Config = { endpoints: [], rooms: [], channels: [], errors: [] }

  for (const entry of (value ?? '').split(';').map(part => part.trim()).filter(part => part !== '').slice(0, 24)) {
    const at = entry.indexOf(':')
    const kind = entry.slice(0, at)
    const rest = entry.slice(at + 1)

    if (kind === 'endpoint') {
      const eq = rest.indexOf('=')
      const [baseUrl = '', keyEnv = '', model = ''] = rest.slice(eq + 1).split('|').map(part => part.trim())
      const name = rest.slice(0, Math.max(eq, 0)).trim()

      if (eq < 0 || !NAME.test(name)) config.errors.push(`endpoint "${entry.slice(0, 30)}": the name is a lowercase word (endpoint:<name>=<base-url>|<KEY_ENV>|<model>)`)
      else if (!isBaseUrl(baseUrl)) config.errors.push(`endpoint ${name}: the base URL must be https (or http to a local or tailnet address), with no credentials, query or fragment`)
      else if (keyEnv !== 'NONE' && !ENV_NAME.test(keyEnv)) config.errors.push(`endpoint ${name}: the key is named by an environment variable (UPPER_SNAKE), or NONE; a key itself is never accepted here`)
      else if (keyEnv !== 'NONE' && NOT_A_MODEL_KEY.test(keyEnv)) config.errors.push(`endpoint ${name}: ${keyEnv} is not a model key; an endpoint is only given the key of a model provider`)
      else if (!MODEL.test(model)) config.errors.push(`endpoint ${name}: no model named`)
      else if (config.endpoints.some(held => held.name === name)) config.errors.push(`endpoint ${name}: named twice`)
      else config.endpoints.push({ name, baseUrl: baseUrl.replace(/\/+$/, ''), keyEnv, model })
    } else if (kind === 'bbs' && ROOM.test(rest)) config.rooms.push(rest)
    else if (kind === 'x' && CHANNEL.test(rest)) config.channels.push(rest)
    else config.errors.push(`"${entry.slice(0, 40)}" is not endpoint:, bbs: or x: with a valid value`)
  }

  return config
}

/** The endpoints with OpenRouter defaulted in, unless the person named their own `openrouter`. */
export const endpointsOf = (config: Config): Endpoint[] => (config.endpoints.some(held => held.name === OPENROUTER.name) ? config.endpoints : [...config.endpoints, OPENROUTER])

export type PeerRef = { host: string; trusted: boolean }

/** The peers in the federation helper's `peers.json` (`peers[].host` and `.trusted`); anything else is dropped. */
export function peersOf(text: string | null): PeerRef[] {
  if (text === null) return []

  try {
    const list = (JSON.parse(text) as { peers?: unknown }).peers

    return Array.isArray(list) ? list.flatMap(item => (typeof item === 'object' && item !== null && typeof (item as { host?: unknown }).host === 'string' && HOST.test((item as { host: string }).host) ? [{ host: (item as { host: string }).host, trusted: (item as { trusted?: unknown }).trusted === true }] : [])).slice(0, 40) : []
  } catch {
    return []
  }
}

export type AgentRef = { id: string; name: string }

export type TargetInput = { agents: readonly AgentRef[]; peers: readonly PeerRef[]; config: Config; hasHive: boolean; hasCodex: boolean }

const mention = (value: string): string => value.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-+|-+$/g, '').slice(0, 24)

/** Every target the console can address now, in a stable order: the main session, then agents, the hive, channels, peers, Codex and endpoints. */
export function targetsOf(input: TargetInput): Target[] {
  const out: Target[] = [
    { id: 'claude', label: 'Claude (this session)', transport: 'prompt', leaves: 'machine', leavesText: 'nothing beyond what a turn of this session sends to the model', cost: 'session-turn', costText: 'a visible turn of this session, billed as any turn is', arrival: 'turn', arrivalText: 'its answer is the next turn in the transcript, not captured here', ref: 'main' },
  ]

  for (const agent of input.agents.slice(0, 20)) {
    const id = mention(agent.name)

    if (id !== '' && !out.some(held => held.id === id)) out.push({ id, label: `agent ${agent.name}`, transport: 'send-message', leaves: 'machine', leavesText: 'nothing: queued inside this session', cost: 'session-turn', costText: 'the agent\'s own next turn', arrival: 'none', arrivalText: 'in its inbox at once, read when its current turn ends (minutes into a long turn); its answer is not routed back here', ref: agent.id })
  }

  if (input.hasHive) out.push({ id: 'hive', label: 'ruflo hive-mind', transport: 'hive', leaves: 'machine', leavesText: 'nothing: written to the hive\'s shared memory', cost: 'free', costText: 'no model call', arrival: 'none', arrivalText: 'appended to the hive memory; a worker sees it only if its own turn reads it (a proposal needs votes)', ref: 'hive' })

  if (input.hasHive) out.push({ id: 'hive-propose', label: 'ruflo hive consensus (a proposal)', transport: 'hive', leaves: 'machine', leavesText: 'nothing: a proposal in the hive state', cost: 'free', costText: 'no model call', arrival: 'none', arrivalText: 'workers vote on it; a pass binds no agent', ref: 'propose' })

  out.push({ id: 'task', label: 'ruflo task note', transport: 'task', leaves: 'machine', leavesText: 'nothing: written to the task store', cost: 'free', costText: 'no model call', arrival: 'none', arrivalText: 'the task record changes; an agent sees it only when it reads the task', ref: 'task' })

  for (const room of input.config.rooms) out.push({ id: `bbs-${mention(room)}`, label: `agentbbs room ${room}`, transport: 'bbs', leaves: 'machine', leavesText: 'a message in the room log on this machine, and to its peers if the room syncs', cost: 'free', costText: 'no model call', arrival: 'polled', arrivalText: 'read back with federation_bbs_watch while the thread is open', ref: room })

  for (const channel of input.config.channels) out.push({ id: `x-${mention(channel.replace(':', '-'))}`, label: `x channel ${channel}`, transport: 'x-channel', leaves: 'internet', leavesText: `a message to the relay (${channel.startsWith('prv:') ? 'encrypted under the channel key' : 'PUBLIC: anyone can read it'}) signed with your key`, cost: 'free', costText: 'no model call', arrival: 'polled', arrivalText: 'read back with x_federation_channel_read while the thread is open', ref: channel })

  for (const peer of input.peers) out.push({ id: `peer-${mention(peer.host)}`, label: `peer ${peer.host}${peer.trusted ? '' : ' (not trusted: needs your confirm)'}`, transport: 'peer', leaves: 'tailnet', leavesText: `the prompt, over ssh to ${peer.host}, run as \`claude -p\` there with that machine's own permissions and files`, cost: 'peer-session', costText: `a headless Claude run on ${peer.host}, billed to that machine's login`, arrival: 'immediate', arrivalText: 'the peer\'s stdout comes back when it finishes (up to 10 minutes)', ref: peer.host })

  if (input.hasCodex) out.push({ id: 'codex', label: 'Codex (codex exec, read-only)', transport: 'codex', leaves: 'internet', leavesText: 'the prompt, to OpenAI via the codex CLI, run in a read-only sandbox here', cost: 'local-cli', costText: 'the codex CLI\'s own login; its usage is not read here', arrival: 'immediate', arrivalText: 'its final message comes back when it finishes (up to 5 minutes)', ref: 'codex' })

  for (const endpoint of endpointsOf(input.config)) out.push({ id: endpoint.name, label: `${endpoint.name} (${endpoint.model})`, transport: 'http', leaves: endpoint.baseUrl.startsWith('https://') ? 'internet' : 'machine', leavesText: `the prompt, to ${new URL(endpoint.baseUrl).host}${endpoint.keyEnv === 'NONE' ? ' with no key' : `, with the key from $${endpoint.keyEnv} (never shown or stored)`}`, cost: 'metered', costText: 'metered by the provider; the tokens it reports are shown, a price is not guessed', arrival: 'immediate', arrivalText: 'the answer comes back in the same request', ref: endpoint.name })

  return out
}

export type Mentions = { targets: Target[]; unknown: string[]; body: string }

/** `@name` words at the start or after a space pick targets (`@all` picks the agents, the hive and the rooms: what stays on this machine; anything that leaves it is named); the rest is the body. */
export function parseMentions(text: string, targets: readonly Target[]): Mentions {
  const picked: Target[] = []
  const unknown: string[] = []
  const kept: string[] = []

  for (const word of text.trim().split(/\s+/)) {
    const match = /^@([A-Za-z0-9][A-Za-z0-9-]{0,31})$/.exec(word)

    if (match === null) {
      kept.push(word)
      continue
    }

    const name = (match[1] ?? '').toLowerCase()
    const found = targets.find(target => target.id === name)

    if (name === 'all') {
      for (const target of targets.filter(held => held.leaves === 'machine' && ['send-message', 'hive', 'bbs'].includes(held.transport) && held.ref !== 'propose')) if (!picked.includes(target)) picked.push(target)

      continue
    }

    if (found !== undefined) {
      if (!picked.includes(found)) picked.push(found)
    } else unknown.push(name)
  }

  return { targets: picked.slice(0, MAX_FANOUT), unknown, body: kept.join(' ').trim() }
}

/** At most this many targets get one question: a longer list is cut, and the composer says so. */
export const MAX_FANOUT = 6

files.hooks/data/automate.ts:
/**
 * What the Automation and Neural views read and keep: the lists a click asked for (workflows, templates, sessions,
 * config, autopilot), the training runs of this session, and the checks every typed value passes before it becomes an
 * argv element. Read against @claude-flow/cli 3.51.1 (mcp-tools/{workflow,session,config,task}-tools.ts,
 * commands/{autopilot,neural}.ts) and what it printed in a scratch project. Pure: no `$`, nothing here runs anything.
 *
 * Config values are masked as they are parsed, so a secret never reaches the state, the result panel or a log line.
 */
import { ARGV_TEXT_MAX } from '../full-text'
import { closeOf } from './json-span'
import { idOf, msOf, numberOf, plain, recordOf, stringOf } from './parse'
import { countOf, ratioOf } from './safe'

export type WorkflowRow = { id: string; name: string; status: string; steps: number; createdAtMs?: number }
export type TemplateRow = { id: string; name: string; steps: number }
export type SessionRow = { id: string; name: string; savedAtMs?: number }
/** `shown` is the value as the view may draw it: a secret-looking key or value is already replaced by a mask. */
export type ConfigRow = { key: string; shown: string; source: string; isSecret: boolean }
export type AutopilotStatus = { isEnabled: boolean; iterations: number; maxIterations: number; timeoutMinutes: number; done: number; total: number; percent: number; sources: string[] }
/** One `neural train` run: the pattern, the epochs asked, and the loss its table printed (Final Loss, else Avg Loss). */
export type TrainRun = { pattern: string; epochs: number; loss?: number; seconds?: number; backend?: string; atMs: number }

export type AutoState = {
  workflows: WorkflowRow[] | null
  templates: TemplateRow[] | null
  sessions: SessionRow[] | null
  config: ConfigRow[] | null
  autopilot: AutopilotStatus | null
  trains: TrainRun[]
  /** The pattern and epochs the train buttons use, picked in the view. */
  pattern: Pattern
  epochs: number
}

export const emptyAuto = (): AutoState => ({ workflows: null, templates: null, sessions: null, config: null, autopilot: null, trains: [], pattern: 'coordination', epochs: 20 })

/** The pattern types `neural train -p` takes (commands/neural.ts). */
export const PATTERNS = ['coordination', 'optimization', 'prediction', 'security', 'testing'] as const
export type Pattern = (typeof PATTERNS)[number]
export const EPOCHS = [10, 20, 50, 100] as const

/** The twelve background workers `hooks_worker-dispatch` accepts (its trigger enum), in its own order. */
export const WORKER_NAMES = ['ultralearn', 'optimize', 'consolidate', 'predict', 'audit', 'map', 'preload', 'deepdive', 'document', 'refactor', 'benchmark', 'testgaps'] as const
export type WorkerName = (typeof WORKER_NAMES)[number]

/** What each worker does, in `hooks worker list`'s words. */
export const WORKER_ABOUT: Record<WorkerName, string> = {
  ultralearn: 'deep knowledge acquisition',
  optimize: 'performance optimization',
  consolidate: 'memory consolidation',
  predict: 'predictive preloading',
  audit: 'security analysis',
  map: 'codebase mapping',
  preload: 'resource preloading',
  deepdive: 'deep code analysis',
  document: 'auto-documentation',
  refactor: 'refactoring suggestions',
  benchmark: 'performance benchmarking',
  testgaps: 'test coverage analysis',
}

/** Typed text: letters, digits, spaces, punctuation and symbols (an em dash or curly quotes too); `plain` drops controls. */
const TYPED = /^[\p{L}\p{N}\p{M}\p{P}\p{S} ]+$/u

/** Free text from a field as one argv element or JSON string: cleaned, 1..max characters, not starting with -. */
export function freeText(value: string, max = ARGV_TEXT_MAX): string | null {
  const text = plain(value, max + 1)

  return text === '' || text.length > max || text.startsWith('-') || !TYPED.test(text) ? null : text
}

const DANGEROUS = new Set(['__proto__', 'constructor', 'prototype'])

/** A config key in dot notation (`swarm.maxAgents`): word segments only, at most ten, nothing that reaches a prototype. */
export function configKeyOf(value: string): string | null {
  const key = value.trim()

  return key.length <= 128 && /^[A-Za-z][A-Za-z0-9_-]*(\.[A-Za-z0-9_-]+){0,9}$/.test(key) && !key.split('.').some(part => DANGEROUS.has(part)) ? key : null
}

/** A key that names a credential: its value is never drawn, and the console never sets it (the confirm row prints argv). */
export const isSecretKey = (key: string): boolean => /(key|token|secret|passw|credential|auth|cookie|private|bearer|jwt|session)/i.test(key)

/** A value shaped like a credential, whatever its key says: provider prefixes, JWTs, or a long unbroken token. */
export function looksSecret(value: unknown): boolean {
  if (typeof value !== 'string') return false

  return /^(sk-|sk_|pk_|rk_|ghp_|gho_|ghs_|github_pat_|glpat-|xox[abpors]-|AKIA|ASIA|AIza|eyJ|npm_|hf_)/.test(value) || /^[A-Za-z0-9+/_=-]{32,}$/.test(value)
}

export const MASK = '•••••• (hidden)'

/** A config value as the view may show it: a mask for anything secret, else the value, short. */
export function shownValue(key: string, value: unknown): { shown: string; isSecret: boolean } {
  const isSecret = isSecretKey(key) || looksSecret(value) || (recordOf(value) !== null && Object.entries(recordOf(value) ?? {}).some(([inner, field]) => isSecretKey(inner) || looksSecret(field)))

  if (isSecret) return { shown: MASK, isSecret: true }
  if (value === undefined) return { shown: 'n/a', isSecret: false }

  return { shown: plain(typeof value === 'string' ? value : JSON.stringify(value) ?? String(value), 80), isSecret: false }
}

/** A typed config value as `config_set` stores it: true/false and plain numbers keep their type, the rest is text. */
export function configValueOf(value: string): string | number | boolean | null {
  const text = value.trim()

  if (text === 'true' || text === 'false') return text === 'true'
  if (/^-?\d{1,15}(\.\d{1,6})?$/.test(text)) return Number(text)

  return freeText(text, ARGV_TEXT_MAX)
}

/** `key value` from one field: the key, then the rest as the value. */
export function keyValueOf(value: string): { key: string; value: string | number | boolean } | null {
  const [head = '', ...rest] = value.trim().split(/\s+/)
  const key = configKeyOf(head)
  const parsed = rest.length === 0 ? null : configValueOf(rest.join(' '))

  return key === null || parsed === null ? null : { key, value: parsed }
}

/** A path inside the project for a tool to read: relative, no `..`, no leading dash or dot-dot, plain characters. */
export function relPathOf(value: string): string | null {
  const path = value.trim()

  return path.length <= 200 && /^[A-Za-z0-9_.][A-Za-z0-9_./-]*$/.test(path) && !path.split('/').includes('..') && !path.startsWith('-') ? path : null
}

/**
 * The JSON object a run printed: from the first line that opens one to the last brace. Not `jsonAfter`, which also takes
 * a line opening `[`: `hooks route` prints `[hooks] Semantic router initialized…` before its JSON.
 */
export function objectIn(stdout: string): Record<string, unknown> | null {
  const text = stdout.length > 1_000_000 ? stdout.slice(0, 1_000_000) : stdout
  const start = /^[ \t]*\{/m.exec(text)

  if (start === null) return null

  try {
    return recordOf(JSON.parse(text.slice(start.index, closeOf(text, start.index) + 1)))
  } catch {
    return null
  }
}

const rows = (value: unknown): Record<string, unknown>[] => (Array.isArray(value) ? value : []).slice(0, 50).map(recordOf).filter((row): row is Record<string, unknown> => row !== null)

/** `workflow_list`: `{ workflows: [{ workflowId, name, status, stepCount, createdAt }] }`, newest first. */
export function parseWorkflows(stdout: string): WorkflowRow[] | null {
  const value = objectIn(stdout)

  if (value === null || !Array.isArray(value.workflows)) return null

  return rows(value.workflows).flatMap(row => {
    const id = idOf(row.workflowId)
    const createdAtMs = msOf(row.createdAt)

    return id === null ? [] : [{ id, name: plain(row.name, 60) || id, status: stringOf(row.status, 20) ?? 'unknown', steps: countOf(row.stepCount) ?? 0, ...(createdAtMs !== undefined && { createdAtMs }) }]
  })
}

/** `workflow_template { action: list }`: `{ templates: [{ templateId, name, stepCount }] }`. */
export function parseTemplates(stdout: string): TemplateRow[] | null {
  const value = objectIn(stdout)

  if (value === null || !Array.isArray(value.templates)) return null

  return rows(value.templates).flatMap(row => {
    const id = idOf(row.templateId)

    return id === null ? [] : [{ id, name: plain(row.name, 60) || id, steps: countOf(row.stepCount) ?? 0 }]
  })
}

/** `session_list`: `{ sessions: [{ sessionId, name, savedAt }] }`, newest first. */
export function parseSessions(stdout: string): SessionRow[] | null {
  const value = objectIn(stdout)

  if (value === null || !Array.isArray(value.sessions)) return null

  return rows(value.sessions).flatMap(row => {
    const id = idOf(row.sessionId)
    const savedAtMs = msOf(row.savedAt)

    return id === null || id === 'unknown' ? [] : [{ id, name: plain(row.name, 60) || id, ...(savedAtMs !== undefined && { savedAtMs }) }]
  })
}

/** `config_list`: `{ configs: [{ key, value, source }] }`, every value masked here, before it is kept. */
export function parseConfig(stdout: string): ConfigRow[] | null {
  const value = objectIn(stdout)

  if (value === null || !Array.isArray(value.configs)) return null

  return rows(value.configs)
    .slice(0, 40)
    .flatMap(row => {
      const key = typeof row.key === 'string' ? configKeyOf(row.key) : null

      return key === null ? [] : [{ key, ...shownValue(key, row.value), source: stringOf(row.source, 20) ?? 'n/a' }]
    })
}

/** `autopilot status --json`: enabled, iterations of max, the timeout, and task progress. */
export function parseAutopilot(stdout: string): AutopilotStatus | null {
  const value = objectIn(stdout)
  const tasks = recordOf(value?.tasks)

  if (value === null || typeof value.enabled !== 'boolean') return null

  return {
    isEnabled: value.enabled,
    iterations: countOf(value.iterations) ?? 0,
    maxIterations: countOf(value.maxIterations) ?? 0,
    timeoutMinutes: countOf(value.timeoutMinutes) ?? 0,
    done: countOf(tasks?.completed) ?? 0,
    total: countOf(tasks?.total) ?? 0,
    percent: Math.round((ratioOf((numberOf(tasks?.percent) ?? 0) / 100) ?? 0) * 100),
    sources: (Array.isArray(value.taskSources) ? value.taskSources : []).slice(0, 6).flatMap(source => (typeof source === 'string' ? [plain(source, 24)] : [])),
  }
}

/** The `| Metric | Value |` rows a CLI table printed, as [name, value] pairs; the header row is left out. */
export function tableRows(stdout: string): [string, string][] {
  return stdout.split('\n').flatMap(line => {
    const match = /^\|\s*([^|]+?)\s*\|\s*([^|]*?)\s*\|$/.exec(line.trim())

    return match === null || match[1] === 'Metric' ? [] : [[plain(match[1], 40), plain(match[2], 80)] as [string, string]]
  })
}

/** What `neural train` printed, as one run: its loss from Final Loss (native backend) or Avg Loss (JS fallback). */
export function parseTrain(stdout: string, atMs: number): TrainRun | null {
  const table = new Map(tableRows(stdout))
  const epochs = Number(table.get('Epochs'))
  const pattern = table.get('Pattern Type')

  if (pattern === undefined || !Number.isFinite(epochs)) return null

  const loss = Number(table.get('Final Loss') ?? table.get('Avg Loss'))
  const seconds = Number.parseFloat(table.get('Total Time') ?? '')
  const backend = table.get('Backend')

  return {
    pattern: plain(pattern, 20),
    epochs,
    atMs,
    ...(Number.isFinite(loss) && { loss }),
    ...(Number.isFinite(seconds) && { seconds }),
    ...(backend !== undefined && backend !== '' && { backend: backend.split(' ')[0] }),
  }
}

const BARS = '▁▂▃▄▅▆▇█'

/** A series as a one-line sparkline, highest value tallest; a flat or single series sits mid-height. */
export function sparkline(values: readonly number[]): string {
  const finite = values.filter(Number.isFinite)
  const lo = Math.min(...finite)
  const hi = Math.max(...finite)

  return finite.map(value => BARS[hi === lo ? 3 : Math.round(((value - lo) / (hi - lo)) * (BARS.length - 1))]).join('')
}

/**
 * A stored task status as one of ruflo's five, reading the spellings older CLIs stored as written ("complete", "done",
 * "canceled", "running"); anything else is returned trimmed and lower-cased, so callers that compare against the five
 * treat it as not finished. Every reader that decides on status goes through this (kanban, mission scheduling, cancel).
 */
export function taskStatusOf(status: string | undefined): string {
  const key = (status ?? '').trim().toLowerCase()

  if (key === 'complete' || key === 'done') return 'completed'
  if (key === 'canceled') return 'cancelled'
  if (key === 'running' || key === 'in-progress' || key === 'inprogress') return 'in_progress'

  return key
}

/**
 * A task's lane on the kanban: what ruflo's task tools write (pending, in_progress, completed, failed, cancelled), plus the
 * spellings older CLIs stored as written (task_update took any string): "complete" sat in PENDING and inflated its count.
 */
export function laneOf(status: string): 'pending' | 'running' | 'done' {
  const key = status.trim().toLowerCase()

  if (/^(in_progress|in-progress|inprogress|running|assigned|active|busy)$/.test(key)) return 'running'
  if (/^(completed|complete|done|failed|cancelled|canceled|error)$/.test(key)) return 'done'

  return 'pending'
}

